  1→#!/usr/bin/env bun
  2→/**
  3→ * onboard-centre.ts — Automated Code Ninjas Centre Onboarding
  4→ *
  5→ * Provisions a new centre across Twilio, Retell, Cekura, ChatDash, and Hiya
  6→ * in a single command. Executes 10 sequential steps with rollback-aware logging.
  7→ *
  8→ * Usage:
  9→ *   bun /root/lead-reactivation-github/scripts/onboard-centre.ts \
 10→ *     --name "Leaside" --area-code "647" --country CA \
 11→ *     --owner-name "Sharmila" --owner-email "sharmila@example.com"
 12→ *
 13→ * See onboard-centre.help.md for full documentation.
 14→ */
 15→
 16→import { parseArgs } from "util";
 17→
 18→// ─────────────────────────────────────────────────────────────
 19→// Configuration
 20→// ─────────────────────────────────────────────────────────────
 21→
 22→const TWILIO_SID = "AC[REDACTED-TWILIO-SID]";
 23→const TWILIO_TOKEN = "518f1bbbbd163747a5a8ecb873d6fbd5";
 24→const TWILIO_BASE = "https://api.twilio.com/2010-04-01";
 25→
 26→const RETELL_KEY = "key_[REDACTED]";
 27→const RETELL_BASE = "https://api.retellai.com";
 28→
 29→const CEKURA_KEY = "c1d54ef4f8e8ed6e5e94033d78b4765060a5a116030e7281a03ed926efb1e2fc";
 30→const CEKURA_BASE = "https://api.cekura.ai";
 31→const CEKURA_PROJECT = 3782;
 32→const CEKURA_PERSONALITY = 693;
 33→const CEKURA_TIER2_CRON_ID = 429;
 34→
 35→const SOURCE_AGENT_ID = "agent_0c6c32b61cb506fefb6ac247f4";
 36→const SOURCE_LLM_ID = "llm_44111168b1a2a469f50891b26e34";
 37→
 38→const SIP_TERMINATION_URI = "xprime.pstn.twilio.com";
 39→const SIP_AUTH_USER = "xprime";
 40→const SIP_AUTH_PASS = "Twiliopass!7";
 41→
 42→const N8N_WEBHOOK = "https://xprime17.app.n8n.cloud/webhook/ac45848d-559c-4b66-9058-5d76b8476531";
 43→
 44→// Metric IDs used in scenarios
 45→const METRIC_EXPECTED_OUTCOME = 118041;
 46→const METRIC_TOUR_BOOKING = 118268;
 47→const METRIC_NATURAL_FLOW = 118273;
 48→const METRIC_LOCATION_ACCURACY = 119652;
 49→
 50→// ─────────────────────────────────────────────────────────────
 51→// CLI Argument Parsing
 52→// ─────────────────────────────────────────────────────────────
 53→
 54→const HELP_TEXT = `
 55→onboard-centre — Automate full Code Ninjas centre onboarding
 56→
 57→USAGE:
 58→  bun onboard-centre.ts --name <name> --area-code <code> [options]
 59→
 60→REQUIRED:
 61→  --name          Centre name (e.g., "Leaside")
 62→  --area-code     Twilio area code for phone number search (e.g., "647")
 63→
 64→OPTIONS:
 65→  --country       Country code: CA or US (default: CA)
 66→  --owner-name    Centre owner first name (for ChatDash client)
 67→  --owner-email   Centre owner email (for ChatDash login)
 68→  --dry-run       Show what would happen without executing API calls
 69→  --help, -h      Show this help message
 70→
 71→EXAMPLES:
 72→  # Full onboarding (Canadian centre)
 73→  bun onboard-centre.ts --name "Leaside" --area-code "647" \\
 74→    --owner-name "Sharmila" --owner-email "sharmila@example.com"
 75→
 76→  # US centre
 77→  bun onboard-centre.ts --name "Frisco" --area-code "469" --country US \\
 78→    --owner-name "Mike" --owner-email "mike@example.com"
 79→
 80→  # Dry run — preview without executing
 81→  bun onboard-centre.ts --name "Leaside" --area-code "647" --dry-run
 82→
 83→STEPS EXECUTED:
 84→  1. Twilio    — Provision phone number
 85→  2. Retell    — Create LLM copy (with centre name hardcoded)
 86→  3. Retell    — Clone agent
 87→  4. Retell    — Import phone number + link to agent
 88→  5. Cekura    — Create test agent
 89→  6. Cekura    — Create Tier 2 scenarios (Location Verify + Happy Path)
 90→  7. Cekura    — Print Tier 2 cron update instructions
 91→  8. ChatDash  — Print manual setup instructions
 92→  9. Hiya      — Print branded caller ID instructions
 93→  10. Summary  — Print all created resource IDs
 94→`;
 95→
 96→const { values } = parseArgs({
 97→  args: Bun.argv.slice(2),
 98→  options: {
 99→    name: { type: "string" },
100→    "area-code": { type: "string" },
101→    country: { type: "string", default: "CA" },
102→    "owner-name": { type: "string" },
103→    "owner-email": { type: "string" },
104→    "dry-run": { type: "boolean", default: false },
105→    help: { type: "boolean", short: "h", default: false },
106→  },
107→});
108→
109→if (values.help) {
110→  console.log(HELP_TEXT);
111→  process.exit(0);
112→}
113→
114→const centreName = values.name;
115→const areaCode = values["area-code"];
116→const country = (values.country ?? "CA").toUpperCase();
117→const ownerName = values["owner-name"] ?? "";
118→const ownerEmail = values["owner-email"] ?? "";
119→const dryRun = values["dry-run"] ?? false;
120→
121→if (!centreName) {
122→  console.error("\x1b[31mError: --name is required\x1b[0m");
123→  console.error('Usage: bun onboard-centre.ts --name "Leaside" --area-code "647"');
124→  process.exit(1);
125→}
126→if (!areaCode) {
127→  console.error("\x1b[31mError: --area-code is required\x1b[0m");
128→  console.error('Usage: bun onboard-centre.ts --name "Leaside" --area-code "647"');
129→  process.exit(1);
130→}
131→if (!["CA", "US"].includes(country)) {
132→  console.error(`\x1b[31mError: --country must be CA or US, got "${country}"\x1b[0m`);
133→  process.exit(1);
134→}
135→
136→// ─────────────────────────────────────────────────────────────
137→// Types
138→// ─────────────────────────────────────────────────────────────
139→
140→interface OnboardingState {
141→  twilioNumber: string | null;
142→  twilioSid: string | null;
143→  retellLlmId: string | null;
144→  retellAgentId: string | null;
145→  retellPhoneId: string | null;
146→  cekuraAgentId: number | null;
147→  cekuraScenarioLocId: number | null;
148→  cekuraScenarioHpId: number | null;
149→}
150→
151→interface TwilioNumber {
152→  phone_number: string;
153→  friendly_name: string;
154→  locality: string;
155→  region: string;
156→}
157→
158→// ─────────────────────────────────────────────────────────────
159→// Logging Utilities
160→// ─────────────────────────────────────────────────────────────
161→
162→const GREEN = "\x1b[32m";
163→const RED = "\x1b[31m";
164→const YELLOW = "\x1b[33m";
165→const CYAN = "\x1b[36m";
166→const BOLD = "\x1b[1m";
167→const DIM = "\x1b[2m";
168→const RESET = "\x1b[0m";
169→
170→function stepHeader(num: number, title: string): void {
171→  console.log(`\n${BOLD}${CYAN}[${"0".repeat(2 - String(num).length)}${num}]${RESET} ${BOLD}${title}${RESET}`);
172→}
173→
174→function success(msg: string): void {
175→  console.log(`  ${GREEN}OK${RESET} ${msg}`);
176→}
177→
178→function fail(msg: string): void {
179→  console.log(`  ${RED}FAIL${RESET} ${msg}`);
180→}
181→
182→function warn(msg: string): void {
183→  console.log(`  ${YELLOW}WARN${RESET} ${msg}`);
184→}
185→
186→function info(msg: string): void {
187→  console.log(`  ${DIM}${msg}${RESET}`);
188→}
189→
190→function dryLog(msg: string): void {
191→  console.log(`  ${YELLOW}[DRY-RUN]${RESET} ${msg}`);
192→}
193→
194→// ─────────────────────────────────────────────────────────────
195→// HTTP Helpers
196→// ─────────────────────────────────────────────────────────────
197→
198→async function twilioGet<T>(path: string): Promise<T> {
199→  const url = `${TWILIO_BASE}/Accounts/${TWILIO_SID}${path}`;
200→  const auth = Buffer.from(`${TWILIO_SID}:${TWILIO_TOKEN}`).toString("base64");
201→  const res = await fetch(url, {
202→    headers: { Authorization: `Basic ${auth}` },
203→  });
204→  if (!res.ok) {
205→    const body = await res.text();
206→    throw new Error(`Twilio GET ${path} → ${res.status}: ${body}`);
207→  }
208→  return res.json() as Promise<T>;
209→}
210→
211→async function twilioPost<T>(path: string, formData: Record<string, string>): Promise<T> {
212→  const url = `${TWILIO_BASE}/Accounts/${TWILIO_SID}${path}`;
213→  const auth = Buffer.from(`${TWILIO_SID}:${TWILIO_TOKEN}`).toString("base64");
214→  const body = new URLSearchParams(formData).toString();
215→  const res = await fetch(url, {
216→    method: "POST",
217→    headers: {
218→      Authorization: `Basic ${auth}`,
219→      "Content-Type": "application/x-www-form-urlencoded",
220→    },
221→    body,
222→  });
223→  if (!res.ok) {
224→    const text = await res.text();
225→    throw new Error(`Twilio POST ${path} → ${res.status}: ${text}`);
226→  }
227→  return res.json() as Promise<T>;
228→}
229→
230→async function retellGet<T>(path: string): Promise<T> {
231→  const res = await fetch(`${RETELL_BASE}${path}`, {
232→    headers: { Authorization: `Bearer ${RETELL_KEY}` },
233→  });
234→  if (!res.ok) {
235→    const body = await res.text();
236→    throw new Error(`Retell GET ${path} → ${res.status}: ${body}`);
237→  }
238→  return res.json() as Promise<T>;
239→}
240→
241→async function retellPost<T>(path: string, data: unknown): Promise<T> {
242→  const res = await fetch(`${RETELL_BASE}${path}`, {
243→    method: "POST",
244→    headers: {
245→      Authorization: `Bearer ${RETELL_KEY}`,
246→      "Content-Type": "application/json",
247→    },
248→    body: JSON.stringify(data),
249→  });
250→  if (!res.ok) {
251→    const body = await res.text();
252→    throw new Error(`Retell POST ${path} → ${res.status}: ${body}`);
253→  }
254→  return res.json() as Promise<T>;
255→}
256→
257→async function cekuraPost<T>(path: string, data: unknown): Promise<T> {
258→  const res = await fetch(`${CEKURA_BASE}${path}`, {
259→    method: "POST",
260→    headers: {
261→      "X-CEKURA-API-KEY": CEKURA_KEY,
262→      "Content-Type": "application/json",
263→    },
264→    body: JSON.stringify(data),
265→  });
266→  if (!res.ok) {
267→    const body = await res.text();
268→    throw new Error(`Cekura POST ${path} → ${res.status}: ${body}`);
269→  }
270→  return res.json() as Promise<T>;
271→}
272→
273→// ─────────────────────────────────────────────────────────────
274→// Step 1: Twilio — Provision Phone Number
275→// ─────────────────────────────────────────────────────────────
276→
277→async function step1_twilioProvision(state: OnboardingState): Promise<void> {
278→  stepHeader(1, "Twilio - Provision Phone Number");
279→
280→  if (dryRun) {
281→    dryLog(`Would search for ${country} numbers with area code ${areaCode}`);
282→    dryLog(`Would purchase first available and name it "CNKB-${centreName}"`);
283→    state.twilioNumber = `+${areaCode}5550100`;
284→    state.twilioSid = "PN_dry_run_sid";
285→    return;
286→  }
287→
288→  info(`Searching for available ${country} numbers in area code ${areaCode}...`);
289→
290→  const searchPath = `/AvailablePhoneNumbers/${country}/Local.json?AreaCode=${areaCode}&Limit=5`;
291→  const searchResult = await twilioGet<{ available_phone_numbers: TwilioNumber[] }>(searchPath);
292→  const available = searchResult.available_phone_numbers;
293→
294→  if (!available || available.length === 0) {
295→    throw new Error(`No available numbers found for area code ${areaCode} in ${country}`);
296→  }
297→
298→  info(`Found ${available.length} available number(s):`);
299→  for (const num of available) {
300→    info(`  ${num.phone_number} (${num.locality || "unknown"}, ${num.region || "unknown"})`);
301→  }
302→
303→  const chosen = available[0];
304→  info(`Purchasing ${chosen.phone_number}...`);
305→
306→  const purchased = await twilioPost<{ sid: string; phone_number: string }>(
307→    "/IncomingPhoneNumbers.json",
308→    {
309→      PhoneNumber: chosen.phone_number,
310→      FriendlyName: `CNKB-${centreName}`,
311→    }
312→  );
313→
314→  state.twilioNumber = purchased.phone_number;
315→  state.twilioSid = purchased.sid;
316→  success(`Provisioned ${purchased.phone_number} (SID: ${purchased.sid})`);
317→}
318→
319→// ─────────────────────────────────────────────────────────────
320→// Step 2: Retell — Create LLM Copy
321→// ─────────────────────────────────────────────────────────────
322→
323→async function step2_retellLlm(state: OnboardingState): Promise<void> {
324→  stepHeader(2, "Retell - Create LLM Copy");
325→
326→  if (dryRun) {
327→    dryLog(`Would GET source LLM ${SOURCE_LLM_ID}`);
328→    dryLog(`Would replace {{LOCATION_NAME}} with "${centreName}" in general_prompt and begin_message`);
329→    dryLog("Would POST /create-retell-llm with modified copy");
330→    state.retellLlmId = "llm_dry_run_id";
331→    return;
332→  }
333→
334→  info(`Fetching source LLM ${SOURCE_LLM_ID}...`);
335→  const sourceLlm = await retellGet<Record<string, unknown>>(`/get-retell-llm/${SOURCE_LLM_ID}`);
336→
337→  // Strip fields that cannot be set on create
338→  const stripped = { ...sourceLlm };
339→  delete stripped.llm_id;
340→  delete stripped.version;
341→  delete stripped.last_modification_timestamp;
342→  delete stripped.is_published;
343→
344→  // Replace template variable with hardcoded centre name
345→  if (typeof stripped.general_prompt === "string") {
346→    stripped.general_prompt = stripped.general_prompt.replace(/\{\{LOCATION_NAME\}\}/g, centreName);
347→    info(`Replaced {{LOCATION_NAME}} in general_prompt`);
348→  }
349→  if (typeof stripped.begin_message === "string") {
350→    stripped.begin_message = stripped.begin_message.replace(/\{\{LOCATION_NAME\}\}/g, centreName);
351→    info(`Replaced {{LOCATION_NAME}} in begin_message`);
352→  }
353→
354→  info("Creating new LLM...");
355→  const newLlm = await retellPost<{ llm_id: string }>("/create-retell-llm", stripped);
356→
357→  state.retellLlmId = newLlm.llm_id;
358→  success(`Created LLM ${newLlm.llm_id}`);
359→}
360→
361→// ─────────────────────────────────────────────────────────────
362→// Step 3: Retell — Clone Agent
363→// ─────────────────────────────────────────────────────────────
364→
365→async function step3_retellAgent(state: OnboardingState): Promise<void> {
366→  stepHeader(3, "Retell - Clone Agent");
367→
368→  if (dryRun) {
369→    dryLog(`Would GET source agent ${SOURCE_AGENT_ID}`);
370→    dryLog(`Would create clone named "CNKB-${centreName}" with LLM ${state.retellLlmId}`);
371→    state.retellAgentId = "agent_dry_run_id";
372→    return;
373→  }
374→
375→  info(`Fetching source agent ${SOURCE_AGENT_ID}...`);
376→  const sourceAgent = await retellGet<Record<string, unknown>>(`/get-agent/${SOURCE_AGENT_ID}`);
377→
378→  // Strip fields that cannot be set on create
379→  const stripped = { ...sourceAgent };
380→  delete stripped.agent_id;
381→  delete stripped.version;
382→  delete stripped.is_published;
383→  delete stripped.last_modification_timestamp;
384→  delete stripped.version_title;
385→
386→  // Set the new agent's identity
387→  stripped.agent_name = `CNKB-${centreName}`;
388→
389→  // Point to the newly created LLM at version 0 (fresh LLM = version 0 is current)
390→  stripped.response_engine = {
391→    type: "retell-llm",
392→    llm_id: state.retellLlmId,
393→    version: 0,
394→  };
395→
396→  // Remove webhook — will be set after ChatDash agent creation
397→  delete stripped.webhook_url;
398→
399→  info("Creating agent clone...");
400→  const newAgent = await retellPost<{ agent_id: string }>("/create-agent", stripped);
401→
402→  state.retellAgentId = newAgent.agent_id;
403→  success(`Created agent ${newAgent.agent_id} (CNKB-${centreName})`);
404→}
405→
406→// ─────────────────────────────────────────────────────────────
407→// Step 4: Retell — Import Phone Number
408→// ─────────────────────────────────────────────────────────────
409→
410→async function step4_retellPhone(state: OnboardingState): Promise<void> {
411→  stepHeader(4, "Retell - Import Phone Number");
412→
413→  if (dryRun) {
414→    dryLog(`Would import ${state.twilioNumber} to Retell via SIP trunk ${SIP_TERMINATION_URI}`);
415→    dryLog(`Would set outbound agent to ${state.retellAgentId}`);
416→    state.retellPhoneId = "phone_dry_run_id";
417→    return;
418→  }
419→
420→  info(`Importing ${state.twilioNumber} to Retell...`);
421→
422→  const result = await retellPost<{ phone_number: string; phone_number_id?: string }>(
423→    "/import-phone-number",
424→    {
425→      phone_number: state.twilioNumber,
426→      termination_uri: SIP_TERMINATION_URI,
427→      nickname: centreName,
428→      outbound_agent_id: state.retellAgentId,
429→      sip_trunk_auth_username: SIP_AUTH_USER,
430→      sip_trunk_auth_password: SIP_AUTH_PASS,
431→    }
432→  );
433→
434→  state.retellPhoneId = result.phone_number_id ?? result.phone_number;
435→  success(`Imported ${state.twilioNumber} (ID: ${state.retellPhoneId})`);
436→}
437→
438→// ─────────────────────────────────────────────────────────────
439→// Step 5: Cekura — Create Agent
440→// ─────────────────────────────────────────────────────────────
441→
442→async function step5_cekuraAgent(state: OnboardingState): Promise<void> {
443→  stepHeader(5, "Cekura - Create Test Agent");
444→
445→  if (dryRun) {
446→    dryLog(`Would create Cekura agent "CNKB - ${centreName}" in project ${CEKURA_PROJECT}`);
447→    dryLog(`Would link to Retell agent ${state.retellAgentId} with phone ${state.twilioNumber}`);
448→    state.cekuraAgentId = 99999;
449→    return;
450→  }
451→
452→  info(`Creating Cekura agent for CNKB - ${centreName}...`);
453→
454→  const result = await cekuraPost<{ id: number }>("/test_framework/v1/aiagents/", {
455→    project: CEKURA_PROJECT,
456→    agent_name: `CNKB - ${centreName}`,
457→    contact_number: state.twilioNumber,
458→    inbound: false,
459→    description: `Code Ninjas ${centreName} clone. Smoke test for template variable resolution.`,
460→    language: "en",
461→    assistant_id: state.retellAgentId,
462→    chat_assistant_id: state.retellAgentId,
463→    llm_model: "gpt-4.1",
464→    outbound_auto_call: true,
465→    assistant_provider: "retell",
466→    retell_api_key: RETELL_KEY,
467→    transcript_provider: "retell",
468→  });
469→
470→  state.cekuraAgentId = result.id;
471→  success(`Created Cekura agent ${result.id}`);
472→}
473→
474→// ─────────────────────────────────────────────────────────────
475→// Step 6: Cekura — Create Tier 2 Scenarios
476→// ─────────────────────────────────────────────────────────────
477→
478→async function step6_cekuraScenarios(state: OnboardingState): Promise<void> {
479→  stepHeader(6, "Cekura - Create Tier 2 Scenarios");
480→
481→  // Location Verification scenario
482→  const locPayload = {
483→    name: `Location Verification - ${centreName}`,
484→    agent: state.cekuraAgentId,
485→    project: CEKURA_PROJECT,
486→    personality: CEKURA_PERSONALITY,
487→    tags: ["tier2", "location-verify"],
488→    first_message: "Hello",
489→    instructions: [
490→      `You are Sam Taylor, a parent who received a call.`,
491→      `You want to verify which location is calling you.`,
492→      `Follow these steps:`,
493→      `1. When the agent introduces themselves, confirm you are Sam.`,
494→      `2. When asked if you have a minute, say: Sure, but which Code Ninjas location is this? I want to make sure I have the right one.`,
495→      `3. Listen carefully to what location name the agent gives. It should say ${centreName}.`,
496→      `4. If they say the correct location (${centreName}), say: Great, that is the one near us. I am interested but need to call back later. Thanks!`,
497→      `5. If they say a different location, say: Oh, I thought this was ${centreName}. Is this not the ${centreName} location?`,
498→      `6. End the call politely either way.`,
499→    ].join(" "),
500→    expected_outcome_prompt: `Agent correctly identifies itself as calling from Code Ninjas ${centreName} (not East Gwillimbury or any other location). The location name must match exactly: ${centreName}.`,
501→    scenario_language: "en",
502→    scenario_type: "instruction",
503→    metrics: [METRIC_EXPECTED_OUTCOME, METRIC_NATURAL_FLOW, METRIC_LOCATION_ACCURACY],
504→  };
505→
506→  // Happy Path Smoke scenario
507→  const hpPayload = {
508→    name: `Happy Path Smoke - ${centreName}`,
509→    agent: state.cekuraAgentId,
510→    project: CEKURA_PROJECT,
511→    personality: CEKURA_PERSONALITY,
512→    tags: ["tier2", "happy-path-smoke"],
513→    first_message: "Hello",
514→    instructions: [
515→      `You are Jamie Brooks, a parent interested in Code Ninjas for your 9-year-old son named Lucas who likes Minecraft.`,
516→      `Follow these steps:`,
517→      `1. When the agent introduces themselves, confirm you are Jamie.`,
518→      `2. When asked if you have a minute, say yes.`,
519→      `3. When asked about your child, mention Lucas is 9 and loves Minecraft.`,
520→      `4. When offered a tour, accept a weekend time.`,
521→      `5. Confirm the booking and end the call politely.`,
522→    ].join(" "),
523→    expected_outcome_prompt: `Agent successfully introduces itself, asks about the caller's child, and offers to book a tour. Basic conversational flow is natural and the agent mentions Code Ninjas ${centreName}.`,
524→    scenario_language: "en",
525→    scenario_type: "instruction",
526→    metrics: [METRIC_EXPECTED_OUTCOME, METRIC_TOUR_BOOKING, METRIC_NATURAL_FLOW],
527→  };
528→
529→  if (dryRun) {
530→    dryLog(`Would create scenario: "Location Verification - ${centreName}"`);
531→    dryLog(`Would create scenario: "Happy Path Smoke - ${centreName}"`);
532→    state.cekuraScenarioLocId = 999901;
533→    state.cekuraScenarioHpId = 999902;
534→    return;
535→  }
536→
537→  info(`Creating Location Verification scenario...`);
538→  const locResult = await cekuraPost<{ id: number }>(
539→    "/test_framework/v1/scenarios/",
540→    locPayload
541→  );
542→  state.cekuraScenarioLocId = locResult.id;
543→  success(`Created scenario ${locResult.id}: Location Verification - ${centreName}`);
544→
545→  info(`Creating Happy Path Smoke scenario...`);
546→  const hpResult = await cekuraPost<{ id: number }>(
547→    "/test_framework/v1/scenarios/",
548→    hpPayload
549→  );
550→  state.cekuraScenarioHpId = hpResult.id;
