198→async function twilioGet<T>(path: string): Promise<T> {
199→  const url = `${TWILIO_BASE}/Accounts/${TWILIO_SID}${path}`;
200→  const auth = Buffer.from(`${TWILIO_SID}:${TWILIO_TOKEN}`).toString("base64");
201→  const res = await fetch(url, {
202→    headers: { Authorization: `Basic ${auth}` },
203→  });
204→  if (!res.ok) {
205→    const body = await res.text();
206→    throw new Error(`Twilio GET ${path} → ${res.status}: ${body}`);
207→  }
208→  return res.json() as Promise<T>;
209→}
210→
211→async function twilioPost<T>(path: string, formData: Record<string, string>): Promise<T> {
212→  const url = `${TWILIO_BASE}/Accounts/${TWILIO_SID}${path}`;
213→  const auth = Buffer.from(`${TWILIO_SID}:${TWILIO_TOKEN}`).toString("base64");
214→  const body = new URLSearchParams(formData).toString();
215→  const res = await fetch(url, {
216→    method: "POST",
217→    headers: {
218→      Authorization: `Basic ${auth}`,
219→      "Content-Type": "application/x-www-form-urlencoded",
220→    },
221→    body,
222→  });
223→  if (!res.ok) {
224→    const text = await res.text();
225→    throw new Error(`Twilio POST ${path} → ${res.status}: ${text}`);
226→  }
227→  return res.json() as Promise<T>;
228→}
