708→async function main(): Promise<void> {
709→  console.log(`\n${BOLD}${CYAN}===============================================${RESET}`);
710→  console.log(`${BOLD}${CYAN} Code Ninjas Centre Onboarding: ${centreName}${RESET}`);
711→  console.log(`${BOLD}${CYAN}===============================================${RESET}`);
712→  console.log(`  Country: ${country} | Area Code: ${areaCode}`);
713→  if (ownerName) console.log(`  Owner: ${ownerName} <${ownerEmail}>`);
714→  if (dryRun) console.log(`  ${YELLOW}${BOLD}MODE: DRY RUN${RESET}`);
715→
716→  const state: OnboardingState = {
717→    twilioNumber: null,
718→    twilioSid: null,
719→    retellLlmId: null,
720→    retellAgentId: null,
721→    retellPhoneId: null,
722→    cekuraAgentId: null,
723→    cekuraScenarioLocId: null,
724→    cekuraScenarioHpId: null,
725→  };
726→
727→  const completed: string[] = [];
728→  const failed: string[] = [];
729→
730→  // Steps 1-6 are API-dependent and sequential
731→  const steps: Array<{
732→    name: string;
733→    fn: (state: OnboardingState) => Promise<void> | void;
734→  }> = [
735→    { name: "Twilio Provision", fn: step1_twilioProvision },
736→    { name: "Retell LLM", fn: step2_retellLlm },
737→    { name: "Retell Agent", fn: step3_retellAgent },
738→    { name: "Retell Phone Import", fn: step4_retellPhone },
739→    { name: "Cekura Agent", fn: step5_cekuraAgent },
740→    { name: "Cekura Scenarios", fn: step6_cekuraScenarios },
741→  ];
742→
743→  for (const step of steps) {
744→    try {
745→      await step.fn(state);
746→      completed.push(step.name);
747→    } catch (err) {
748→      const msg = err instanceof Error ? err.message : String(err);
749→      fail(msg);
750→      failed.push(step.name);
751→
752→      // Report partial progress and bail
753→      console.log(`\n${RED}${BOLD}Onboarding ABORTED at step: ${step.name}${RESET}`);
754→      console.log(`\n  ${GREEN}Completed:${RESET} ${completed.join(", ") || "none"}`);
755→      console.log(`  ${RED}Failed:${RESET} ${failed.join(", ")}`);
756→
757→      if (completed.length > 0) {
758→        console.log(`\n  ${YELLOW}Partial resources created (may need manual cleanup):${RESET}`);
759→        if (state.twilioNumber) console.log(`    Twilio: ${state.twilioNumber} (SID: ${state.twilioSid})`);
760→        if (state.retellLlmId) console.log(`    Retell LLM: ${state.retellLlmId}`);
761→        if (state.retellAgentId) console.log(`    Retell Agent: ${state.retellAgentId}`);
762→        if (state.retellPhoneId) console.log(`    Retell Phone: ${state.retellPhoneId}`);
763→        if (state.cekuraAgentId) console.log(`    Cekura Agent: ${state.cekuraAgentId}`);
764→      }
765→
766→      process.exit(1);
767→    }
768→  }
769→
770→  // Steps 7-11 are informational (no API calls), always succeed
771→  step7_cekuraCron(state);
772→  step8_chatDash(state);
773→  step9_googleSheet(state);
774→  step10_hiya(state);
775→  step11_summary(state);
776→}
777→
778→main().catch((err) => {
779→  console.error(`\n${RED}${BOLD}Fatal error:${RESET}`, err);
780→  process.exit(1);
781→});
