 *     --name "Leaside" --area-code "647" --country CA \
 *     --owner-name "Sharmila" --owner-email "sharmila@example.com"
 *
 * See onboard-centre.help.md for full documentation.
 */

import { parseArgs } from "util";

// ─────────────────────────────────────────────────────────────
// Configuration
// ─────────────────────────────────────────────────────────────

const TWILIO_SID = "AC[REDACTED-TWILIO-SID]";
const TWILIO_TOKEN = "518f1bbbbd163747a5a8ecb873d6fbd5";
const TWILIO_BASE = "https://api.twilio.com/2010-04-01";

const RETELL_KEY = "key_[REDACTED]";
const RETELL_BASE = "https://api.retellai.com";

const CEKURA_KEY = "c1d54ef4f8e8ed6e5e94033d78b4765060a5a116030e7281a03ed926efb1e2fc";
const CEKURA_BASE = "https://api.cekura.ai";
const CEKURA_PROJECT = 3782;
const CEKURA_PERSONALITY = 693;
const CEKURA_TIER2_CRON_ID = 429;

const SOURCE_AGENT_ID = "agent_0c6c32b61cb506fefb6ac247f4";
const SOURCE_LLM_ID = "llm_44111168b1a2a469f50891b26e34";

const SIP_TERMINATION_URI = "xprime.pstn.twilio.com";
const SIP_AUTH_USER = "xprime";
const SIP_AUTH_PASS = "Twiliopass!7";

const N8N_WEBHOOK = "https://xprime17.app.n8n.cloud/webhook/ac45848d-559c-4b66-9058-5d76b8476531";

// Metric IDs used in scenarios
const METRIC_EXPECTED_OUTCOME = 118041;
const METRIC_TOUR_BOOKING = 118268;
const METRIC_NATURAL_FLOW = 118273;
const METRIC_LOCATION_ACCURACY = 119652;

// ─────────────────────────────────────────────────────────────
// CLI Argument Parsing
// ─────────────────────────────────────────────────────────────

const HELP_TEXT = `
onboard-centre — Automate full Code Ninjas centre onboarding

USAGE:
  bun onboard-centre.ts --name <name> --area-code <code> [options]

REQUIRED:
  --name          Centre name (e.g., "Leaside")
  --area-code     Twilio area code for phone number search (e.g., "647")

OPTIONS:
  --country       Country code: CA or US (default: CA)
  --owner-name    Centre owner first name (for ChatDash client)
  --owner-email   Centre owner email (for ChatDash login)
  --dry-run       Show what would happen without executing API calls
  --help, -h      Show this help message

EXAMPLES:
  # Full onboarding (Canadian centre)
  bun onboard-centre.ts --name "Leaside" --area-code "647" \\
    --owner-name "Sharmila" --owner-email "sharmila@example.com"

  # US centre
  bun onboard-centre.ts --name "Frisco" --area-code "469" --country US \\
    --owner-name "Mike" --owner-email "mike@example.com"

  # Dry run — preview without executing
  bun onboard-centre.ts --name "Leaside" --area-code "647" --dry-run

STEPS EXECUTED:
  1. Twilio    — Provision phone number
  2. Retell    — Create LLM copy (with centre name hardcoded)
  3. Retell    — Clone agent
  4. Retell    — Import phone number + link to agent
  5. Cekura    — Create test agent
  6. Cekura    — Create Tier 2 scenarios (Location Verify + Happy Path)
  7. Cekura    — Print Tier 2 cron update instructions
  8. ChatDash  — Print manual setup instructions
  9. Hiya      — Print branded caller ID instructions
  10. Summary  — Print all created resource IDs
`;

const { values } = parseArgs({
  args: Bun.argv.slice(2),
  options: {
    name: { type: "string" },
    "area-code": { type: "string" },
    country: { type: "string", default: "CA" },
    "owner-name": { type: "string" },
    "owner-email": { type: "string" },
    "dry-run": { type: "boolean", default: false },
    help: { type: "boolean", short: "h", default: false },
  },
});

if (values.help) {
  console.log(HELP_TEXT);
  process.exit(0);
}

const centreName = values.name;
const areaCode = values["area-code"];
const country = (values.country ?? "CA").toUpperCase();
const ownerName = values["owner-name"] ?? "";
const ownerEmail = values["owner-email"] ?? "";
const dryRun = values["dry-run"] ?? false;

if (!centreName) {
  console.error("\x1b[31mError: --name is required\x1b[0m");
  console.error('Usage: bun onboard-centre.ts --name "Leaside" --area-code "647"');
  process.exit(1);
}
if (!areaCode) {
  console.error("\x1b[31mError: --area-code is required\x1b[0m");
  console.error('Usage: bun onboard-centre.ts --name "Leaside" --area-code "647"');
  process.exit(1);
}
if (!["CA", "US"].includes(country)) {
  console.error(`\x1b[31mError: --country must be CA or US, got "${country}"\x1b[0m`);
  process.exit(1);
}

// ─────────────────────────────────────────────────────────────
// Types
// ─────────────────────────────────────────────────────────────

interface OnboardingState {
  twilioNumber: string | null;
  twilioSid: string | null;
  retellLlmId: string | null;
  retellAgentId: string | null;
  retellPhoneId: string | null;
  cekuraAgentId: number | null;
  cekuraScenarioLocId: number | null;
  cekuraScenarioHpId: number | null;
}

interface TwilioNumber {
  phone_number: string;
  friendly_name: string;
  locality: string;
  region: string;
}

// ─────────────────────────────────────────────────────────────
// Logging Utilities
// ─────────────────────────────────────────────────────────────

const GREEN = "\x1b[32m";
const RED = "\x1b[31m";
const YELLOW = "\x1b[33m";
const CYAN = "\x1b[36m";
const BOLD = "\x1b[1m";
const DIM = "\x1b[2m";
const RESET = "\x1b[0m";

function stepHeader(num: number, title: string): void {
  console.log(`\n${BOLD}${CYAN}[${"0".repeat(2 - String(num).length)}${num}]${RESET} ${BOLD}${title}${RESET}`);
}

function success(msg: string): void {
  console.log(`  ${GREEN}OK${RESET} ${msg}`);
}

function fail(msg: string): void {
  console.log(`  ${RED}FAIL${RESET} ${msg}`);
}

function warn(msg: string): void {
  console.log(`  ${YELLOW}WARN${RESET} ${msg}`);
}

function info(msg: string): void {
  console.log(`  ${DIM}${msg}${RESET}`);
}

function dryLog(msg: string): void {
  console.log(`  ${YELLOW}[DRY-RUN]${RESET} ${msg}`);
}

// ─────────────────────────────────────────────────────────────
// HTTP Helpers
// ─────────────────────────────────────────────────────────────

async function twilioGet<T>(path: string): Promise<T> {
  const url = `${TWILIO_BASE}/Accounts/${TWILIO_SID}${path}`;
  const auth = Buffer.from(`${TWILIO_SID}:${TWILIO_TOKEN}`).toString("base64");
  const res = await fetch(url, {
    headers: { Authorization: `Basic ${auth}` },
  });
  if (!res.ok) {
    const body = await res.text();
    throw new Error(`Twilio GET ${path} → ${res.status}: ${body}`);
  }
  return res.json() as Promise<T>;
}

async function twilioPost<T>(path: string, formData: Record<string, string>): Promise<T> {
  const url = `${TWILIO_BASE}/Accounts/${TWILIO_SID}${path}`;
  const auth = Buffer.from(`${TWILIO_SID}:${TWILIO_TOKEN}`).toString("base64");
  const body = new URLSearchParams(formData).toString();
  const res = await fetch(url, {
    method: "POST",
    headers: {
      Authorization: `Basic ${auth}`,
      "Content-Type": "application/x-www-form-urlencoded",
    },
    body,
  });
  if (!res.ok) {
    const text = await res.text();
    throw new Error(`Twilio POST ${path} → ${res.status}: ${text}`);
  }
  return res.json() as Promise<T>;
}

async function retellGet<T>(path: string): Promise<T> {
  const res = await fetch(`${RETELL_BASE}${path}`, {
    headers: { Authorization: `Bearer ${RETELL_KEY}` },
  });
  if (!res.ok) {
    const body = await res.text();
    throw new Error(`Retell GET ${path} → ${res.status}: ${body}`);
  }
  return res.json() as Promise<T>;
}

async function retellPost<T>(path: string, data: unknown): Promise<T> {
  const res = await fetch(`${RETELL_BASE}${path}`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${RETELL_KEY}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify(data),
  });
  if (!res.ok) {
    const body = await res.text();
    throw new Error(`Retell POST ${path} → ${res.status}: ${body}`);
  }
  return res.json() as Promise<T>;
}

async function cekuraPost<T>(path: string, data: unknown): Promise<T> {
  const res = await fetch(`${CEKURA_BASE}${path}`, {
    method: "POST",
    headers: {
      "X-CEKURA-API-KEY": CEKURA_KEY,
      "Content-Type": "application/json",
    },
    body: JSON.stringify(data),
  });
  if (!res.ok) {
    const body = await res.text();
    throw new Error(`Cekura POST ${path} → ${res.status}: ${body}`);
  }
  return res.json() as Promise<T>;
}

// ─────────────────────────────────────────────────────────────
// Step 1: Twilio — Provision Phone Number
// ─────────────────────────────────────────────────────────────

async function step1_twilioProvision(state: OnboardingState): Promise<void> {
  stepHeader(1, "Twilio - Provision Phone Number");

  if (dryRun) {
    dryLog(`Would search for ${country} numbers with area code ${areaCode}`);
    dryLog(`Would purchase first available and name it "CNKB-${centreName}"`);
    state.twilioNumber = `+${areaCode}5550100`;
    state.twilioSid = "PN_dry_run_sid";
    return;
  }

  info(`Searching for available ${country} numbers in area code ${areaCode}...`);

  const searchPath = `/AvailablePhoneNumbers/${country}/Local.json?AreaCode=${areaCode}&Limit=5`;
  const searchResult = await twilioGet<{ available_phone_numbers: TwilioNumber[] }>(searchPath);
  const available = searchResult.available_phone_numbers;

  if (!available || available.length === 0) {
    throw new Error(`No available numbers found for area code ${areaCode} in ${country}`);
  }

  info(`Found ${available.length} available number(s):`);
  for (const num of available) {
    info(`  ${num.phone_number} (${num.locality || "unknown"}, ${num.region || "unknown"})`);
  }

  const chosen = available[0];
  info(`Purchasing ${chosen.phone_number}...`);

  const purchased = await twilioPost<{ sid: string; phone_number: string }>(
    "/IncomingPhoneNumbers.json",
    {
      PhoneNumber: chosen.phone_number,
      FriendlyName: `CNKB-${centreName}`,
    }
  );

  state.twilioNumber = purchased.phone_number;
  state.twilioSid = purchased.sid;
  success(`Provisioned ${purchased.phone_number} (SID: ${purchased.sid})`);
}

// ─────────────────────────────────────────────────────────────
// Step 2: Retell — Create LLM Copy
// ─────────────────────────────────────────────────────────────

async function step2_retellLlm(state: OnboardingState): Promise<void> {
  stepHeader(2, "Retell - Create LLM Copy");

  if (dryRun) {
    dryLog(`Would GET source LLM ${SOURCE_LLM_ID}`);
    dryLog(`Would replace {{LOCATION_NAME}} with "${centreName}" in general_prompt and begin_message`);
    dryLog("Would POST /create-retell-llm with modified copy");
    state.retellLlmId = "llm_dry_run_id";
    return;
  }

  info(`Fetching source LLM ${SOURCE_LLM_ID}...`);
  const sourceLlm = await retellGet<Record<string, unknown>>(`/get-retell-llm/${SOURCE_LLM_ID}`);

  // Strip fields that cannot be set on create
  const stripped = { ...sourceLlm };
  delete stripped.llm_id;
  delete stripped.version;
  delete stripped.last_modification_timestamp;
  delete stripped.is_published;

  // Replace template variable with hardcoded centre name
  if (typeof stripped.general_prompt === "string") {
    stripped.general_prompt = stripped.general_prompt.replace(/\{\{LOCATION_NAME\}\}/g, centreName);
    info(`Replaced {{LOCATION_NAME}} in general_prompt`);
  }
  if (typeof stripped.begin_message === "string") {
    stripped.begin_message = stripped.begin_message.replace(/\{\{LOCATION_NAME\}\}/g, centreName);
    info(`Replaced {{LOCATION_NAME}} in begin_message`);
  }

  info("Creating new LLM...");
  const newLlm = await retellPost<{ llm_id: string }>("/create-retell-llm", stripped);

  state.retellLlmId = newLlm.llm_id;
  success(`Created LLM ${newLlm.llm_id}`);
}

// ─────────────────────────────────────────────────────────────
// Step 3: Retell — Clone Agent
// ─────────────────────────────────────────────────────────────

async function step3_retellAgent(state: OnboardingState): Promise<void> {
  stepHeader(3, "Retell - Clone Agent");

  if (dryRun) {
    dryLog(`Would GET source agent ${SOURCE_AGENT_ID}`);
    dryLog(`Would create clone named "CNKB-${centreName}" with LLM ${state.retellLlmId}`);
    state.retellAgentId = "agent_dry_run_id";
    return;
  }

  info(`Fetching source agent ${SOURCE_AGENT_ID}...`);
  const sourceAgent = await retellGet<Record<string, unknown>>(`/get-agent/${SOURCE_AGENT_ID}`);

  // Strip fields that cannot be set on create
  const stripped = { ...sourceAgent };
  delete stripped.agent_id;
  delete stripped.version;
  delete stripped.is_published;
  delete stripped.last_modification_timestamp;
  delete stripped.version_title;

  // Set the new agent's identity
  stripped.agent_name = `CNKB-${centreName}`;

  // Point to the newly created LLM at version 0 (fresh LLM = version 0 is current)
  stripped.response_engine = {
    type: "retell-llm",
    llm_id: state.retellLlmId,
    version: 0,
  };

  // Remove webhook — will be set after ChatDash agent creation
  delete stripped.webhook_url;

  info("Creating agent clone...");
  const newAgent = await retellPost<{ agent_id: string }>("/create-agent", stripped);

  state.retellAgentId = newAgent.agent_id;
  success(`Created agent ${newAgent.agent_id} (CNKB-${centreName})`);
}

// ─────────────────────────────────────────────────────────────
// Step 4: Retell — Import Phone Number
// ─────────────────────────────────────────────────────────────

async function step4_retellPhone(state: OnboardingState): Promise<void> {
  stepHeader(4, "Retell - Import Phone Number");

  if (dryRun) {
    dryLog(`Would import ${state.twilioNumber} to Retell via SIP trunk ${SIP_TERMINATION_URI}`);
    dryLog(`Would set outbound agent to ${state.retellAgentId}`);
    state.retellPhoneId = "phone_dry_run_id";
    return;
  }

  info(`Importing ${state.twilioNumber} to Retell...`);

  const result = await retellPost<{ phone_number: string; phone_number_id?: string }>(
    "/import-phone-number",
    {
      phone_number: state.twilioNumber,
      termination_uri: SIP_TERMINATION_URI,
      nickname: centreName,
      outbound_agent_id: state.retellAgentId,
      sip_trunk_auth_username: SIP_AUTH_USER,
      sip_trunk_auth_password: SIP_AUTH_PASS,
    }
  );

  state.retellPhoneId = result.phone_number_id ?? result.phone_number;
  success(`Imported ${state.twilioNumber} (ID: ${state.retellPhoneId})`);
}

// ─────────────────────────────────────────────────────────────
// Step 5: Cekura — Create Agent
// ─────────────────────────────────────────────────────────────

async function step5_cekuraAgent(state: OnboardingState): Promise<void> {
  stepHeader(5, "Cekura - Create Test Agent");

  if (dryRun) {
    dryLog(`Would create Cekura agent "CNKB - ${centreName}" in project ${CEKURA_PROJECT}`);
    dryLog(`Would link to Retell agent ${state.retellAgentId} with phone ${state.twilioNumber}`);
    state.cekuraAgentId = 99999;
    return;
  }

  info(`Creating Cekura agent for CNKB - ${centreName}...`);

  const result = await cekuraPost<{ id: number }>("/test_framework/v1/aiagents/", {
    project: CEKURA_PROJECT,
    agent_name: `CNKB - ${centreName}`,
    contact_number: state.twilioNumber,
    inbound: false,
    description: `Code Ninjas ${centreName} clone. Smoke test for template variable resolution.`,
    language: "en",
    assistant_id: state.retellAgentId,
    chat_assistant_id: state.retellAgentId,
    llm_model: "gpt-4.1",
    outbound_auto_call: true,
    assistant_provider: "retell",
    retell_api_key: RETELL_KEY,
    transcript_provider: "retell",
  });

  state.cekuraAgentId = result.id;
  success(`Created Cekura agent ${result.id}`);
}

// ─────────────────────────────────────────────────────────────
// Step 6: Cekura — Create Tier 2 Scenarios
// ─────────────────────────────────────────────────────────────

async function step6_cekuraScenarios(state: OnboardingState): Promise<void> {
  stepHeader(6, "Cekura - Create Tier 2 Scenarios");

  // Location Verification scenario
  const locPayload = {
    name: `Location Verification - ${centreName}`,
    agent: state.cekuraAgentId,
    project: CEKURA_PROJECT,
    personality: CEKURA_PERSONALITY,
    tags: ["tier2", "location-verify"],
    first_message: "Hello",
    instructions: [
      `You are Sam Taylor, a parent who received a call.`,
      `You want to verify which location is calling you.`,
      `Follow these steps:`,
      `1. When the agent introduces themselves, confirm you are Sam.`,
      `2. When asked if you have a minute, say: Sure, but which Code Ninjas location is this? I want to make sure I have the right one.`,
      `3. Listen carefully to what location name the agent gives. It should say ${centreName}.`,
      `4. If they say the correct location (${centreName}), say: Great, that is the one near us. I am interested but need to call back later. Thanks!`,
      `5. If they say a different location, say: Oh, I thought this was ${centreName}. Is this not the ${centreName} location?`,
      `6. End the call politely either way.`,
    ].join(" "),
    expected_outcome_prompt: `Agent correctly identifies itself as calling from Code Ninjas ${centreName} (not East Gwillimbury or any other location). The location name must match exactly: ${centreName}.`,
    scenario_language: "en",
    scenario_type: "instruction",
    metrics: [METRIC_EXPECTED_OUTCOME, METRIC_NATURAL_FLOW, METRIC_LOCATION_ACCURACY],
  };

  // Happy Path Smoke scenario
  const hpPayload = {
    name: `Happy Path Smoke - ${centreName}`,
    agent: state.cekuraAgentId,
    project: CEKURA_PROJECT,
    personality: CEKURA_PERSONALITY,
    tags: ["tier2", "happy-path-smoke"],
    first_message: "Hello",
    instructions: [
      `You are Jamie Brooks, a parent interested in Code Ninjas for your 9-year-old son named Lucas who likes Minecraft.`,
      `Follow these steps:`,
      `1. When the agent introduces themselves, confirm you are Jamie.`,
      `2. When asked if you have a minute, say yes.`,
      `3. When asked about your child, mention Lucas is 9 and loves Minecraft.`,
      `4. When offered a tour, accept a weekend time.`,
      `5. Confirm the booking and end the call politely.`,
    ].join(" "),
    expected_outcome_prompt: `Agent successfully introduces itself, asks about the caller's child, and offers to book a tour. Basic conversational flow is natural and the agent mentions Code Ninjas ${centreName}.`,
    scenario_language: "en",
    scenario_type: "instruction",
    metrics: [METRIC_EXPECTED_OUTCOME, METRIC_TOUR_BOOKING, METRIC_NATURAL_FLOW],
  };

  if (dryRun) {
    dryLog(`Would create scenario: "Location Verification - ${centreName}"`);
    dryLog(`Would create scenario: "Happy Path Smoke - ${centreName}"`);
    state.cekuraScenarioLocId = 999901;
    state.cekuraScenarioHpId = 999902;
    return;
  }

  info(`Creating Location Verification scenario...`);
  const locResult = await cekuraPost<{ id: number }>(
    "/test_framework/v1/scenarios/",
    locPayload
  );
  state.cekuraScenarioLocId = locResult.id;
  success(`Created scenario ${locResult.id}: Location Verification - ${centreName}`);

  info(`Creating Happy Path Smoke scenario...`);
  const hpResult = await cekuraPost<{ id: number }>(
    "/test_framework/v1/scenarios/",
    hpPayload
  );
  state.cekuraScenarioHpId = hpResult.id;
  success(`Created scenario ${hpResult.id}: Happy Path Smoke - ${centreName}`);
}

// ─────────────────────────────────────────────────────────────
// Step 7: Cekura — Tier 2 Cron Update Instructions
// ─────────────────────────────────────────────────────────────

function step7_cekuraCron(state: OnboardingState): void {
  stepHeader(7, "Cekura - Tier 2 Cron Update");

  const locId = state.cekuraScenarioLocId;
  const hpId = state.cekuraScenarioHpId;

  console.log(`
  ${YELLOW}ACTION REQUIRED:${RESET} Update Tier 2 cron job (ID: ${CEKURA_TIER2_CRON_ID})

  Add scenario IDs ${BOLD}${locId}${RESET} and ${BOLD}${hpId}${RESET} to cron ${CEKURA_TIER2_CRON_ID}.

  Via Cekura MCP tool:
    cron_jobs_partial_update(${CEKURA_TIER2_CRON_ID}, { scenarios: [...existing, ${locId}, ${hpId}] })

  Or via curl:
    curl -X PATCH '${CEKURA_BASE}/test_framework/v1/cron_jobs/${CEKURA_TIER2_CRON_ID}/' \\
      -H 'X-CEKURA-API-KEY: ${CEKURA_KEY}' \\
      -H 'Content-Type: application/json' \\
      -d '{"scenarios": [...existing_ids, ${locId}, ${hpId}]}'
`);
}

// ─────────────────────────────────────────────────────────────
// Step 8: ChatDash — Manual Steps
// ─────────────────────────────────────────────────────────────

function step8_chatDash(state: OnboardingState): void {
  stepHeader(8, "ChatDash - Manual Setup");

  const ownerLower = ownerName ? ownerName.toLowerCase() : "<owner_first_name>";
  const nameKebab = centreName.toLowerCase().replace(/\s+/g, "");
  const loginId = ownerName
    ? `${ownerLower}.${nameKebab}`
    : `<first_name>.${nameKebab}`;
  const email = ownerEmail || "<owner_email>";
  const password = `CN${centreName.replace(/\s+/g, "")}2026`;

  console.log(`
  ${YELLOW}MANUAL STEPS REQUIRED${RESET} - ChatDash API is blocked on current plan:

  1. Go to ${BOLD}https://chat-dash.com${RESET} -> Create Agent
     - Name: CNKB-${centreName}
     - Platform: Retell
     - Note the agent ID

  2. Go to Clients -> Create Client
     - Name: Code Ninjas ${centreName}
     - Member name: ${ownerName || "<owner_name>"}
     - Login ID: ${loginId}
     - Email: ${email}
     - Password: ${password}

  3. Assign agent to client

  4. ChatDash auto-sets the Retell webhook when you connect the agent.
     Verify by checking: GET ${RETELL_BASE}/get-agent/${state.retellAgentId}
     The webhook_url should contain: api.chat-dash.com/v1/private/agents/{ID}/import/webhook

  5. Set forwarding URL in ChatDash agent settings:
     ${N8N_WEBHOOK}

  ${BOLD}TIP:${RESET} To discover the ChatDash agent ID programmatically, read the Retell
  agent webhook_url — ChatDash embeds its agent ID in the path automatically.
`);
}

// ─────────────────────────────────────────────────────────────
// Step 9: Google Sheet — Centre Directory Update
// ─────────────────────────────────────────────────────────────

const CENTRE_LOOKUP_SHEET = "1wQAdX3frfxCHK0HmGCKRpzmOx7SFaLP-3nn7AEc0GK0";

function step9_googleSheet(state: OnboardingState): void {
  stepHeader(9, "Google Sheet - Centre Directory");

  const number = (state.twilioNumber ?? "").replace("+", "");
  const agentId = state.retellAgentId ?? "";

  console.log(`
  ${YELLOW}ACTION REQUIRED:${RESET} Update the Centre Lookup sheet

  Sheet: ${BOLD}https://docs.google.com/spreadsheets/d/${CENTRE_LOOKUP_SHEET}/edit${RESET}

  Find the ${BOLD}${centreName}${RESET} row and fill in:
    ${BOLD}from_number${RESET} (column E): ${GREEN}${number}${RESET}
    ${BOLD}agent_id${RESET}    (column J): ${GREEN}${agentId}${RESET}

  This sheet feeds the n8n "End Of Call - Multicentre" workflow.
  Without these values, call routing won't work for ${centreName}.
`);
}

// ─────────────────────────────────────────────────────────────
// Step 10: Hiya — Manual Steps
// ─────────────────────────────────────────────────────────────

function step10_hiya(state: OnboardingState): void {
  stepHeader(10, "Hiya - Branded Caller ID");

  console.log(`
  ${YELLOW}ACTION REQUIRED:${RESET} Register ${BOLD}${state.twilioNumber}${RESET} with Hiya for branded caller ID.

  Display name: ${BOLD}Code Ninjas ${centreName}${RESET}

  Register at: https://hiya.com/branded-caller-id
`);
}

// ─────────────────────────────────────────────────────────────
// Step 10: Summary
// ─────────────────────────────────────────────────────────────

function step11_summary(state: OnboardingState): void {
  stepHeader(11, "Onboarding Summary");

  const pad = (s: string, len: number): string => s.padEnd(len);
  const w = 56;
  const rule = "=".repeat(w);
  const line = (label: string, value: string): string => {
    const content = `  ${pad(label, 22)} ${value}`;
    return `  ${content}`;
  };

  console.log(`
  ${GREEN}${BOLD}${rule}${RESET}
  ${GREEN}${BOLD}  ONBOARDING COMPLETE: Code Ninjas ${centreName}${RESET}
  ${GREEN}${BOLD}${rule}${RESET}
${line("Twilio Number:", state.twilioNumber ?? "FAILED")}
${line("Twilio SID:", state.twilioSid ?? "FAILED")}
${line("Retell LLM:", state.retellLlmId ?? "FAILED")}
${line("Retell Agent:", state.retellAgentId ?? "FAILED")}
${line("Retell Phone:", state.retellPhoneId ?? "FAILED")}
${line("Cekura Agent:", state.cekuraAgentId?.toString() ?? "FAILED")}
${line("Cekura Loc Scenario:", state.cekuraScenarioLocId?.toString() ?? "FAILED")}
${line("Cekura HP Scenario:", state.cekuraScenarioHpId?.toString() ?? "FAILED")}
${line("ChatDash:", "MANUAL - see Step 8")}
${line("Google Sheet:", "MANUAL - see Step 9")}
${line("Hiya:", "MANUAL - see Step 10")}
  ${GREEN}${BOLD}${rule}${RESET}
`);

  if (dryRun) {
    console.log(`  ${YELLOW}${BOLD}This was a DRY RUN. No API calls were made.${RESET}`);
  }
}

// ─────────────────────────────────────────────────────────────
// Main Execution
// ─────────────────────────────────────────────────────────────

async function main(): Promise<void> {
  console.log(`\n${BOLD}${CYAN}===============================================${RESET}`);
  console.log(`${BOLD}${CYAN} Code Ninjas Centre Onboarding: ${centreName}${RESET}`);
  console.log(`${BOLD}${CYAN}===============================================${RESET}`);
  console.log(`  Country: ${country} | Area Code: ${areaCode}`);
  if (ownerName) console.log(`  Owner: ${ownerName} <${ownerEmail}>`);
  if (dryRun) console.log(`  ${YELLOW}${BOLD}MODE: DRY RUN${RESET}`);

  const state: OnboardingState = {
    twilioNumber: null,
    twilioSid: null,
    retellLlmId: null,
    retellAgentId: null,
    retellPhoneId: null,
    cekuraAgentId: null,
    cekuraScenarioLocId: null,
    cekuraScenarioHpId: null,
  };

  const completed: string[] = [];
  const failed: string[] = [];

  // Steps 1-6 are API-dependent and sequential
  const steps: Array<{
    name: string;
    fn: (state: OnboardingState) => Promise<void> | void;
  }> = [
    { name: "Twilio Provision", fn: step1_twilioProvision },
    { name: "Retell LLM", fn: step2_retellLlm },
    { name: "Retell Agent", fn: step3_retellAgent },
    { name: "Retell Phone Import", fn: step4_retellPhone },
    { name: "Cekura Agent", fn: step5_cekuraAgent },
    { name: "Cekura Scenarios", fn: step6_cekuraScenarios },
  ];

  for (const step of steps) {
    try {
      await step.fn(state);
      completed.push(step.name);
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      fail(msg);
      failed.push(step.name);

      // Report partial progress and bail
      console.log(`\n${RED}${BOLD}Onboarding ABORTED at step: ${step.name}${RESET}`);
      console.log(`\n  ${GREEN}Completed:${RESET} ${completed.join(", ") || "none"}`);
      console.log(`  ${RED}Failed:${RESET} ${failed.join(", ")}`);

      if (completed.length > 0) {
        console.log(`\n  ${YELLOW}Partial resources created (may need manual cleanup):${RESET}`);
        if (state.twilioNumber) console.log(`    Twilio: ${state.twilioNumber} (SID: ${state.twilioSid})`);
        if (state.retellLlmId) console.log(`    Retell LLM: ${state.retellLlmId}`);
        if (state.retellAgentId) console.log(`    Retell Agent: ${state.retellAgentId}`);
        if (state.retellPhoneId) console.log(`    Retell Phone: ${state.retellPhoneId}`);
        if (state.cekuraAgentId) console.log(`    Cekura Agent: ${state.cekuraAgentId}`);
      }

      process.exit(1);
    }
  }

  // Steps 7-11 are informational (no API calls), always succeed
  step7_cekuraCron(state);
  step8_chatDash(state);
  step9_googleSheet(state);
  step10_hiya(state);
  step11_summary(state);
}

main().catch((err) => {
  console.error(`\n${RED}${BOLD}Fatal error:${RESET}`, err);
  process.exit(1);
});

