  3→/**
  4→ * SyncPrompt - Batch-sync CNKB prompt to all centre clone LLMs
  5→ *
  6→ * Reads the general_prompt and begin_message from the source LLM (original CNKB)
  7→ * and pushes them to all clone LLMs. Each clone has its own LLM copy because
  8→ * Retell pins agents to a specific LLM version and blocks version changes.
  9→ *
 10→ * Usage:
 11→ *   bun SyncPrompt.ts                  # Dry-run: show diff, don't push
 12→ *   bun SyncPrompt.ts --push           # Push changes to all clones
 13→ *   bun SyncPrompt.ts --status         # Show sync status of all clones
 14→ *   bun SyncPrompt.ts --push --only Canton,Rayford   # Push to specific clones only
 15→ *
 16→ * @version 1.0.0
 17→ */
 18→
 19→import { parseArgs } from "util";
 20→
 21→// ── Configuration ────────────────────────────────────────────────
 22→
 23→const RETELL_API_KEY = process.env.RETELL_API_KEY ?? "key_[REDACTED]";
 24→const RETELL_BASE = "https://api.retellai.com";
 25→
 26→const SOURCE_LLM = {
 27→  name: "CN /w KB (East Gwillimbury)",
 28→  llm_id: "llm_44111168b1a2a469f50891b26e34",
 29→  agent_id: "agent_0c6c32b61cb506fefb6ac247f4",
 30→};
