 96→// ── Retell API helpers ───────────────────────────────────────────
 97→
 98→interface LLMData {
 99→  llm_id: string;
100→  general_prompt: string;
101→  begin_message: string;
102→  version: number;
103→  last_modification_timestamp: number;
104→}
105→
106→async function getLLM(llm_id: string): Promise<LLMData> {
107→  const res = await fetch(`${RETELL_BASE}/get-retell-llm/${llm_id}`, {
108→    headers: { Authorization: `Bearer ${RETELL_API_KEY}` },
109→  });
110→  if (!res.ok) throw new Error(`GET LLM ${llm_id}: ${res.status} ${await res.text()}`);
111→  return res.json() as Promise<LLMData>;
112→}
113→
114→async function updateLLM(llm_id: string, payload: { general_prompt: string; begin_message: string }): Promise<LLMData> {
115→  const res = await fetch(`${RETELL_BASE}/update-retell-llm/${llm_id}`, {
116→    method: "PATCH",
117→    headers: {
118→      Authorization: `Bearer ${RETELL_API_KEY}`,
119→      "Content-Type": "application/json",
120→    },
121→    body: JSON.stringify(payload),
122→  });
123→  if (!res.ok) throw new Error(`PATCH LLM ${llm_id}: ${res.status} ${await res.text()}`);
124→  return res.json() as Promise<LLMData>;
125→}
