127→// ── Diff helpers ─────────────────────────────────────────────────
128→
129→function promptHash(text: string): string {
130→  const h = new Bun.CryptoHasher("sha256");
131→  h.update(text);
132→  return h.digest("hex").slice(0, 12);
133→}
134→
135→function shortDiff(source: string, target: string): string {
136→  if (source === target) return "identical";
137→  const srcLen = source.length;
138→  const tgtLen = target.length;
139→  const lenDiff = srcLen - tgtLen;
140→  const sign = lenDiff > 0 ? "+" : "";
141→  return `${sign}${lenDiff} chars (source: ${srcLen}, target: ${tgtLen})`;
142→}
143→
144→// ── Main ─────────────────────────────────────────────────────────
145→
146→async function main() {
147→  const targets = filterClones();
148→
149→  if (values.status) {
150→    await showStatus(targets);
151→  } else {
152→    await syncPrompt(targets);
153→  }
154→}
