156→function filterClones(): CloneEntry[] {
157→  if (!values.only) return CLONES;
158→  const names = values.only.split(",").map(n => n.trim().toLowerCase());
159→  const filtered = CLONES.filter(c => names.includes(c.name.toLowerCase()));
160→  if (filtered.length === 0) {
161→    console.error(`No clones matched: ${values.only}`);
162→    console.error(`Available: ${CLONES.map(c => c.name).join(", ")}`);
163→    process.exit(1);
164→  }
165→  return filtered;
166→}
