    enabled: "TRUE",
    location_name: centreName,
    from_number: fromNumber,
    testing: "FALSE",
    test_number: "",
    centre_email: centreEmail,
    director: ownerName ?? "",
    agent_id: agentId,
    knowledge_base: "",
