  );
  state.cekuraScenarioHpId = hpResult.id;
  success(`Created scenario ${hpResult.id}: Happy Path Smoke - ${centreName}`);
}

// ─────────────────────────────────────────────────────────────
// Step 7: Cekura — Tier 2 Cron Update Instructions
// ─────────────────────────────────────────────────────────────

function step7_cekuraCron(state: OnboardingState): void {
  stepHeader(7, "Cekura - Tier 2 Cron Update");

  const locId = state.cekuraScenarioLocId;
  const hpId = state.cekuraScenarioHpId;

  console.log(`
  ${YELLOW}ACTION REQUIRED:${RESET} Update Tier 2 cron job (ID: ${CEKURA_TIER2_CRON_ID})

  Add scenario IDs ${BOLD}${locId}${RESET} and ${BOLD}${hpId}${RESET} to cron ${CEKURA_TIER2_CRON_ID}.

