  }

  info(`Writing to Centre Directory sheet via n8n webhook...`);
  const res = await fetch(N8N_CENTRE_DIR_WEBHOOK, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });

  if (!res.ok) {
    throw new Error(`Centre Directory webhook failed: ${res.status} ${await res.text()}`);
  }

  ok(`Centre Directory sheet updated: ${centreCode} | ${fromNumber} | ${agentId}`);
  console.log(`    Sheet: https://docs.google.com/spreadsheets/d/${CENTRE_LOOKUP_SHEET}/edit`);
}

