  const salutation = directorName || "there";
  const fwdAddr = `scott.james1717+${centreCode}@gmail.com`;
  const code = (text: string) => `<code style="background: #e8f0fe; padding: 2px 6px; border-radius: 3px;">${text}</code>`;
  const fwdBox = `<div style="background: #e8f0fe; padding: 12px 16px; border-radius: 6px; margin: 12px 0; font-size: 16px; font-family: monospace;">${fwdAddr}</div>`;

  return `<div style="font-family: Arial, sans-serif; max-width: 700px; margin: 0 auto; color: #333; line-height: 1.6;">
<p>Hi ${salutation},</p>

<p>Welcome! We're getting your AI calling agent set up. It will automatically call new leads within minutes of them inquiring — so they hear from your centre right away.</p>

<p>To get everything working, I need three things from you. I've included step-by-step instructions below.</p>

<hr style="border: none; border-top: 2px solid #1a73e8; margin: 28px 0;">

<h2 style="color: #1a73e8; font-size: 20px;">1. Email Forwarding Setup</h2>

<p>The AI agent is triggered by your Lineleader (CRM) lead notification emails. We need those emails forwarded to a special address so the agent knows when a new lead comes in.</p>

<p><strong>Your forwarding address is:</strong></p>
${fwdBox}

<p>The setup depends on what type of email account receives your Lineleader notifications. <strong>Pick the option that matches your situation:</strong></p>

<!-- OPTION A: GMAIL -->
<div style="background: #f8f9fa; border: 1px solid #ddd; border-radius: 8px; padding: 20px; margin: 20px 0;">
<h3 style="color: #333; margin-top: 0;">Option A: Personal Gmail</h3>
<p><em>Choose this if Lineleader emails go to your personal Gmail address.</em></p>

<h4>Step 1: Create a Filter</h4>
<ol>
<li>Open <a href="https://mail.google.com" style="color: #1a73e8;">Gmail</a> and click the <strong>search bar dropdown arrow</strong> (the small triangle on the right side of the search bar)</li>
<li>In the <strong>"From"</strong> field, type: ${code("noreply@lineleader.com")}</li>
<li>In the <strong>"Subject"</strong> field, type: ${code("New CORE Program Inquiry")}</li>
<li>Click <strong>"Create filter"</strong> (bottom right of the dropdown)</li>
</ol>

<h4>Step 2: Set Up Forwarding</h4>
<ol>
<li>Check the box next to <strong>"Forward it to"</strong></li>
<li>If this is your first time forwarding, click <strong>"Add forwarding address"</strong></li>
<li>Enter: ${code(fwdAddr)}</li>
<li>Click <strong>"Next"</strong> → <strong>"Proceed"</strong> → <strong>"OK"</strong></li>
<li>A confirmation will be sent — <strong>let me know when you've done this step</strong> and I'll confirm it on my end</li>
<li>Once confirmed, come back to the filter and select the forwarding address</li>
<li>Click <strong>"Create filter"</strong></li>
</ol>
<p>That's it! Gmail will now automatically forward matching Lineleader emails.</p>
</div>

<!-- OPTION B: OUTLOOK -->
<div style="background: #f8f9fa; border: 1px solid #ddd; border-radius: 8px; padding: 20px; margin: 20px 0;">
<h3 style="color: #333; margin-top: 0;">Option B: Personal Outlook / Hotmail</h3>
<p><em>Choose this if Lineleader emails go to your personal Outlook.com, Hotmail, or Live.com address.</em></p>

<h4>Step 1: Open Mail Rules</h4>
<ol>
<li>Go to <a href="https://outlook.live.com" style="color: #1a73e8;">outlook.live.com</a> and sign in</li>
<li>Click the <strong>gear icon</strong> in the top right corner</li>
<li>Click <strong>"View all Outlook settings"</strong> at the bottom</li>
<li>Go to <strong>Mail</strong> → <strong>Rules</strong></li>
<li>Click <strong>"+ Add new rule"</strong></li>
</ol>

<h4>Step 2: Set Up the Condition</h4>
<ol>
<li>Name the rule: ${code("CRM Lead Forwarding")}</li>
<li>Under <strong>"Add a condition"</strong>, select <strong>"From"</strong></li>
<li>Type: ${code("noreply@lineleader.com")} and press Enter</li>
<li>Click <strong>"Add another condition"</strong></li>
<li>Select <strong>"Subject includes"</strong></li>
<li>Type: ${code("New CORE Program Inquiry")} and press Enter</li>
</ol>

<h4>Step 3: Set Up the Action</h4>
<ol>
<li>Under <strong>"Add an action"</strong>, select <strong>"Forward to"</strong></li>
<li>Type: ${code(fwdAddr)} and press Enter</li>
<li>Click <strong>"Save"</strong></li>
</ol>
<p>That's it! Outlook will now automatically forward matching Lineleader emails.</p>
</div>

<!-- OPTION C: SHARED INBOX -->
<div style="background: #f8f9fa; border: 1px solid #ddd; border-radius: 8px; padding: 20px; margin: 20px 0;">
<h3 style="color: #333; margin-top: 0;">Option C: Shared Centre Inbox (Microsoft 365)</h3>
<p><em>Choose this if Lineleader emails go to a shared mailbox (like info@yourcentre.com) that multiple staff members access.</em></p>

<p>Shared mailboxes don't support simple forwarding rules, so we'll use <strong>Power Automate</strong> (included free with your Microsoft 365 account).</p>

<h4>Step 1: Open Power Automate</h4>
<ol>
<li>Go to <a href="https://flow.microsoft.com" style="color: #1a73e8;">https://flow.microsoft.com</a></li>
<li>Sign in with your <strong>Microsoft 365 account</strong> (the one that has access to the shared inbox)</li>
</ol>

<h4>Step 2: Create a New Flow</h4>
<ol>
<li>Click <strong>"Create"</strong> in the left menu</li>
<li>Select <strong>"Automated cloud flow"</strong></li>
<li>Name it: <strong>CRM Lead Forwarding</strong></li>
<li>In the search box, search for: <strong>"When a new email arrives in a shared mailbox (V2)"</strong></li>
<li>Select it and click <strong>"Create"</strong></li>
</ol>

<h4>Step 3: Configure the Trigger</h4>
<ol>
<li>Click on the trigger box (it should be the only box on screen) to open its settings</li>
<li>Set <strong>"Original Mailbox Address"</strong> to your centre's shared inbox (e.g., <code>info@yourcentre.com</code>)</li>
<li>Click <strong>"Show all"</strong> under Advanced parameters</li>
<li>Set <strong>"From"</strong> to: ${code("noreply@lineleader.com")}</li>
<li>Set <strong>"Subject Filter"</strong> to: ${code("New CORE Program Inquiry")}</li>
</ol>

<h4>Step 4: Add the Forward Action</h4>
<ol>
<li>Click <strong>"+ New step"</strong></li>
<li>Search for <strong>"Send an email (V2)"</strong> and select it</li>
<li>Configure the fields:
<ul style="list-style-type: disc; margin: 8px 0;">
<li><strong>To:</strong> ${code(fwdAddr)}</li>
<li><strong>Subject:</strong> Click the field, then select <strong>"Subject"</strong> from the dynamic content panel that appears on the right</li>
<li><strong>Body:</strong> Click the field, then select <strong>"Body"</strong> from the dynamic content panel</li>
</ul>
</li>
</ol>

<h4>Step 5: Save and Test</h4>
<ol>
<li>Click <strong>"Save"</strong> in the top right</li>
<li>The flow will now run automatically whenever a matching email arrives in your shared inbox</li>
</ol>
</div>

<hr style="border: none; border-top: 2px solid #1a73e8; margin: 28px 0;">

<h2 style="color: #1a73e8; font-size: 20px;">2. Knowledge Base Setup</h2>

<p>Your AI agent uses a "knowledge base" document to answer questions about your centre — things like programs, pricing, age requirements, hours, and policies. The agent <strong>only</strong> shares information from this document. It won't guess or make things up, so the more complete and accurate it is, the better your calls will sound.</p>

<p>I've prepared a reference template for you. Here's how to set up your own:</p>

<h4>Step 1: Open the Reference Document</h4>
<ol>
<li>Click the link below to open the reference knowledge base:<br><br><a href="${KB_REFERENCE_URL}" style="display: inline-block; background: #1a73e8; color: white; padding: 10px 20px; border-radius: 6px; text-decoration: none; font-weight: bold;">Open Reference Knowledge Base</a></li>
</ol>

<h4>Step 2: Make Your Own Copy</h4>
<ol>
<li>With the document open, go to <strong>File</strong> → <strong>Make a copy</strong></li>
<li>Rename it to something like <strong>"Code Ninjas ${centreDisplayName} - Knowledge Base"</strong></li>
<li>Choose where to save it in your Google Drive (anywhere is fine)</li>
<li>Click <strong>"Make a copy"</strong></li>
</ol>

<h4>Step 3: Customize for Your Centre</h4>
<p>Go through your copy and update the following to match your centre:</p>
<ul>
<li><strong>Programs &amp; pricing</strong> — make sure they match what you currently offer</li>
<li><strong>Hours of operation</strong> — especially if they differ seasonally</li>
<li><strong>Age requirements</strong> — for each program level</li>
<li><strong>Policies</strong> — sibling discounts, trial classes, camps, workshops</li>
<li><strong>Contact info</strong> — your centre's phone number, address, and email</li>
</ul>

<h4>Step 4: Share the Link With Me</h4>
<ol>
<li>In your copy, click the <strong>"Share"</strong> button (top right)</li>
<li>Under <strong>"General access"</strong>, change it from "Restricted" to <strong>"Anyone with the link"</strong></li>
<li>Make sure the permission is set to <strong>"Viewer"</strong> (this is the default)</li>
<li>Click <strong>"Copy link"</strong></li>
<li><strong>Reply to this email</strong> with the link</li>
</ol>

<hr style="border: none; border-top: 2px solid #1a73e8; margin: 28px 0;">

<h2 style="color: #1a73e8; font-size: 20px;">3. Test Phone Number</h2>

<p>Before going live, we'll run a few test calls so you can hear exactly what your leads will experience. The agent will call the number you provide just like it would call a real lead.</p>

<p><strong>Please reply with:</strong></p>
<ul>
<li>A phone number where you (or someone on your team) can answer test calls</li>
<li>A good time to send them (so you're ready to pick up)</li>
</ul>

<hr style="border: none; border-top: 2px solid #1a73e8; margin: 28px 0;">

<h2 style="color: #1a73e8; font-size: 20px;">Quick Summary — What I Need From You</h2>

<table style="border-collapse: collapse; width: 100%; margin: 12px 0;">
<tr style="background: #1a73e8; color: white;"><th style="padding: 10px 12px; text-align: left; width: 40%;">&nbsp;Task</th><th style="padding: 10px 12px; text-align: left;">&nbsp;What to Do</th></tr>
<tr style="background: #f8f9fa;"><td style="padding: 10px 12px; border: 1px solid #ddd;">&nbsp;<strong>Email forwarding</strong></td><td style="padding: 10px 12px; border: 1px solid #ddd;">&nbsp;Set up using Option A, B, or C above</td></tr>
<tr><td style="padding: 10px 12px; border: 1px solid #ddd;">&nbsp;<strong>Knowledge base</strong></td><td style="padding: 10px 12px; border: 1px solid #ddd;">&nbsp;Copy the template, customize, and share the link</td></tr>
<tr style="background: #f8f9fa;"><td style="padding: 10px 12px; border: 1px solid #ddd;">&nbsp;<strong>Test phone number</strong></td><td style="padding: 10px 12px; border: 1px solid #ddd;">&nbsp;Reply with the number + a good time for test calls</td></tr>
</table>

<p>Once I have these three things, we'll run your test calls and you can be live within a day or two. Don't hesitate to reach out if you get stuck on any step — happy to hop on a quick call to walk through it.</p>

<p>Best,<br>Scott</p>
</div>`;
}

async function step10_onboardingEmail(state: OnboardingState): Promise<void> {
  stepHeader(10, "Client Onboarding Email");

  const centreCode = state.discovery?.centreCode ?? centreName.toLowerCase().replace(/\s+/g, "-");
  const directorName = ownerName || state.discovery?.centreCode ? "" : "";

  // If we don't have the director name from CLI, read it from the sheet
  let director = ownerName;
  if (!director) {
    try {
      info("Looking up director name from centre directory sheet...");
      const csvUrl = `https://docs.google.com/spreadsheets/d/${CENTRE_LOOKUP_SHEET}/gviz/tq?tqx=out:csv`;
      const csvRes = await fetch(csvUrl);
      if (csvRes.ok) {
        const csv = await csvRes.text();
        const rows = csv.split("\n");
        for (const row of rows) {
          // Parse CSV fields properly (handles quoted values)
          const cols: string[] = [];
          let current = "";
          let inQuotes = false;
          for (const ch of row) {
            if (ch === '"') { inQuotes = !inQuotes; continue; }
            if (ch === ',' && !inQuotes) { cols.push(current.trim()); current = ""; continue; }
            current += ch;
          }
          cols.push(current.trim());

          // Match on location_name (column 3) — case-insensitive
          const locationName = cols[3] ?? "";
          if (locationName.toLowerCase() === centreName.toLowerCase()) {
            const dirCol = cols[8] ?? "";
            if (dirCol) {
              director = dirCol.split(" ")[0]; // First name only for salutation
              info(`Found director: ${dirCol} (using "${director}" for salutation)`);
            }
            break;
          }
        }
      }
    } catch {
      info("Could not look up director — using generic salutation");
    }
  }

  const subject = `Code Ninjas ${centreName} — AI Agent Setup Instructions`;
  const html = buildOnboardingEmailHtml(director, centreCode, centreName);

  if (dryRun) {
    dryLog(`Would send onboarding email to ${ONBOARDING_EMAIL_TO}`);
    dryLog(`Subject: ${subject}`);
    dryLog(`Salutation: "Hi ${director || "there"}"`);
    dryLog(`Centre code in email: ${centreCode}`);
    dryLog(`Forwarding address: scott.james1717+${centreCode}@gmail.com`);
    return;
  }

  info(`Sending onboarding email to ${ONBOARDING_EMAIL_TO}...`);

  const res = await fetch("https://api.resend.com/emails", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${RESEND_API_KEY}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      from: RESEND_FROM,
      to: [ONBOARDING_EMAIL_TO],
      subject,
      html,
    }),
  });

  if (!res.ok) {
    throw new Error(`Resend API failed: ${res.status} ${await res.text()}`);
  }

  const result = await res.json() as { id: string };
  ok(`Onboarding email sent (ID: ${result.id})`);
  info(`Forward to the centre director when ready`);
}

// ─────────────────────────────────────────────────────────────
// Step 11: Hiya — Manual Steps
// ─────────────────────────────────────────────────────────────

function step11_hiya(state: OnboardingState): void {
  stepHeader(11, "Hiya - Branded Caller ID");

  console.log(`
  ${YELLOW}ACTION REQUIRED:${RESET} Register ${BOLD}${state.twilioNumber}${RESET} with Hiya for branded caller ID.

  Display name: ${BOLD}Code Ninjas ${centreName}${RESET}

  Register at: https://hiya.com/branded-caller-id
`);
}

// ─────────────────────────────────────────────────────────────
// Step 12: Summary
// ─────────────────────────────────────────────────────────────

function step12_summary(state: OnboardingState): void {
  stepHeader(12, "Onboarding Summary");

  const pad = (s: string, len: number): string => s.padEnd(len);
  const w = 56;
  const rule = "=".repeat(w);
  const line = (label: string, value: string): string => {
    const content = `  ${pad(label, 22)} ${value}`;
    return `  ${content}`;
  };

  const d = state.discovery;
  console.log(`
  ${GREEN}${BOLD}${rule}${RESET}
  ${GREEN}${BOLD}  ONBOARDING COMPLETE: Code Ninjas ${centreName}${RESET}
  ${GREEN}${BOLD}${rule}${RESET}
${d ? `${line("Centre Code:", d.centreCode)}
${line("City:", `${d.city}, ${d.state}`)}
${line("Address:", d.address)}
${line("Country:", d.country)}
${line("Area Code:", d.areaCode)}
` : ""}${line("Twilio Sub-Account:", state.subAccountSid ?? "FAILED")}
${line("Twilio Number:", state.twilioNumber ?? "FAILED")}
${line("Twilio SID:", state.twilioSid ?? "FAILED")}
${line("SIP Trunk:", state.trunkDomain ?? "FAILED")}
${line("Retell LLM:", state.retellLlmId ?? "FAILED")}
${line("Retell Agent:", state.retellAgentId ?? "FAILED")}
${line("Retell Phone:", state.retellPhoneId ?? "FAILED")}
${line("Cekura Agent:", state.cekuraAgentId?.toString() ?? "FAILED")}
${line("Cekura Loc Scenario:", state.cekuraScenarioLocId?.toString() ?? "FAILED")}
${line("Cekura HP Scenario:", state.cekuraScenarioHpId?.toString() ?? "FAILED")}
${line("ChatDash:", "MANUAL - see Step 8")}
${line("Google Sheet:", state.discovery?.centreCode ?? "see Step 9")}
${line("Onboarding Email:", "Sent to Scott - see Step 10")}
${line("Hiya:", "MANUAL - see Step 11")}
  ${GREEN}${BOLD}${rule}${RESET}
`);

  if (dryRun) {
    console.log(`  ${YELLOW}${BOLD}This was a DRY RUN. No API calls were made.${RESET}`);
  }
}

// ─────────────────────────────────────────────────────────────
// Main Execution
// ─────────────────────────────────────────────────────────────

async function main(): Promise<void> {
  console.log(`\n${BOLD}${CYAN}===============================================${RESET}`);
  console.log(`${BOLD}${CYAN} Code Ninjas Centre Onboarding: ${centreName}${RESET}`);
  console.log(`${BOLD}${CYAN}===============================================${RESET}`);
  if (ownerName) console.log(`  Owner: ${ownerName} <${ownerEmail}>`);
  if (dryRun) console.log(`  ${YELLOW}${BOLD}MODE: DRY RUN${RESET}`);

  const state: OnboardingState = {
    discovery: null,
    subAccountSid: null,
    subAccountToken: null,
    twilioNumber: null,
    twilioSid: null,
    trunkDomain: null,
    trunkSid: null,
    retellLlmId: null,
    retellAgentId: null,
    retellPhoneId: null,
    cekuraAgentId: null,
    cekuraScenarioLocId: null,
    cekuraScenarioHpId: null,
  };

  const completed: string[] = [];
  const failed: string[] = [];

  // Step 0: Discover centre details if area-code not provided
  if (!areaCode) {
    try {
      const discovery = await step0_discover(centreName);
      state.discovery = discovery;
      areaCode = discovery.areaCode;
      country = country ?? discovery.country;
      completed.push("Discovery");
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      fail(msg);
      console.log(`\n${RED}${BOLD}Discovery failed. Provide --area-code and --country manually.${RESET}`);
      process.exit(1);
    }
  } else {
    country = country ?? "CA";
    info(`Using manual area code: ${areaCode}, country: ${country}`);
  }

  console.log(`  Country: ${country} | Area Code: ${areaCode}`);

  // Steps 1-6 are API-dependent and sequential
  const steps: Array<{
    name: string;
    fn: (state: OnboardingState) => Promise<void> | void;
  }> = [
    { name: "Twilio Provision", fn: step1_twilioProvision },
    { name: "Retell LLM", fn: step2_retellLlm },
    { name: "Retell Agent", fn: step3_retellAgent },
    { name: "Retell Phone Import", fn: step4_retellPhone },
    { name: "Cekura Agent", fn: step5_cekuraAgent },
    { name: "Cekura Scenarios", fn: step6_cekuraScenarios },
  ];

  for (const step of steps) {
    try {
      await step.fn(state);
      completed.push(step.name);
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      fail(msg);
      failed.push(step.name);

      // Report partial progress and bail
      console.log(`\n${RED}${BOLD}Onboarding ABORTED at step: ${step.name}${RESET}`);
      console.log(`\n  ${GREEN}Completed:${RESET} ${completed.join(", ") || "none"}`);
      console.log(`  ${RED}Failed:${RESET} ${failed.join(", ")}`);

      if (completed.length > 0) {
        console.log(`\n  ${YELLOW}Partial resources created (may need manual cleanup):${RESET}`);
        if (state.subAccountSid) console.log(`    Twilio Sub-Account: ${state.subAccountSid}`);
        if (state.twilioNumber) console.log(`    Twilio Phone: ${state.twilioNumber} (SID: ${state.twilioSid})`);
        if (state.trunkSid) console.log(`    Twilio Trunk: ${state.trunkSid} (${state.trunkDomain})`);
        if (state.retellLlmId) console.log(`    Retell LLM: ${state.retellLlmId}`);
        if (state.retellAgentId) console.log(`    Retell Agent: ${state.retellAgentId}`);
        if (state.retellPhoneId) console.log(`    Retell Phone: ${state.retellPhoneId}`);
        if (state.cekuraAgentId) console.log(`    Cekura Agent: ${state.cekuraAgentId}`);
      }

      process.exit(1);
    }
  }

  // Step 7-8 are informational (no API calls), always succeed
  step7_cekuraCron(state);
  step8_chatDash(state);

  // Step 9 writes to Google Sheet via n8n webhook
  try {
    await step9_googleSheet(state);
    completed.push("Google Sheet");
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    fail(`Google Sheet update failed: ${msg}`);
    console.log(`  ${YELLOW}Manual fallback:${RESET} Update sheet at https://docs.google.com/spreadsheets/d/${CENTRE_LOOKUP_SHEET}/edit`);
  }

  // Step 10 sends the client onboarding email
  try {
    await step10_onboardingEmail(state);
    completed.push("Onboarding Email");
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    fail(`Onboarding email failed: ${msg}`);
  }

  // Steps 11-12 are informational, always succeed
  step11_hiya(state);
  step12_summary(state);
}

main().catch((err) => {
  console.error(`\n${RED}${BOLD}Fatal error:${RESET}`, err);
  process.exit(1);
});

