// ─────────────────────────────────────────────────────────────
// Step 12: Internal Checklist Email (Manual Items for Scott)
// ─────────────────────────────────────────────────────────────

function buildInternalChecklistHtml(state: OnboardingState): string {
  const code = (text: string) => `<code style="background:#e8f0fe;padding:2px 6px;border-radius:3px;font-family:monospace;color:#1a73e8;">${text}</code>`;
  const centreCode = state.discovery?.centreCode ?? centreName.toLowerCase().replace(/\s+/g, "-");
  const phone = state.twilioNumber ?? "UNKNOWN";
  const agentId = state.retellAgentId ?? "UNKNOWN";
  const locScenario = state.cekuraScenarioLocId?.toString() ?? "UNKNOWN";
  const hpScenario = state.cekuraScenarioHpId?.toString() ?? "UNKNOWN";
  const ownerLower = ownerName ? ownerName.toLowerCase() : "&lt;owner_first_name&gt;";
  const nameKebab = centreName.toLowerCase().replace(/\s+/g, "");
  const loginId = ownerName ? `${ownerLower}.${nameKebab}` : `&lt;first_name&gt;.${nameKebab}`;
  const email = ownerEmail || "&lt;owner_email&gt;";
  const password = `CN${centreName.replace(/\s+/g, "")}2026`;

  return `<div style="font-family: -apple-system, BlinkMacSystemFont, sans-serif; max-width: 680px; margin: 0 auto; color: #333; line-height: 1.6;">

<div style="background: #d97706; color: white; padding: 24px; border-radius: 8px 8px 0 0; text-align: center;">
<h1 style="margin: 0; font-size: 22px;">INTERNAL &mdash; Code Ninjas ${centreName} Manual Checklist</h1>
</div>

<div style="padding: 24px; border: 1px solid #ddd; border-top: none; border-radius: 0 0 8px 8px;">

<p>The automated onboarding for <strong>Code Ninjas ${centreName}</strong> is complete. The following items require manual action.</p>

<!-- QUICK REFERENCE -->
<table style="width: 100%; border-collapse: collapse; margin: 20px 0;">
<tr style="background: #f8f9fa;"><td style="padding: 8px 14px; border: 1px solid #ddd; font-weight: bold; width: 40%;">Centre Code</td><td style="padding: 8px 14px; border: 1px solid #ddd;">${code(centreCode)}</td></tr>
<tr><td style="padding: 8px 14px; border: 1px solid #ddd; font-weight: bold;">Phone Number</td><td style="padding: 8px 14px; border: 1px solid #ddd;">${code(phone)}</td></tr>
<tr style="background: #f8f9fa;"><td style="padding: 8px 14px; border: 1px solid #ddd; font-weight: bold;">Retell Agent ID</td><td style="padding: 8px 14px; border: 1px solid #ddd;">${code(agentId)}</td></tr>
</table>

<!-- TASK 1: CEKURA CRON -->
<div style="background: #fef3c7; border-left: 4px solid #d97706; padding: 16px 20px; margin: 20px 0; border-radius: 0 8px 8px 0;">
<h3 style="margin-top: 0; color: #92400e;">1. Update Cekura Tier 2 Cron Job</h3>
<p>Add the new scenario IDs to cron job ${code(String(CEKURA_TIER2_CRON_ID))}:</p>
<ul>
<li>Location Verification: ${code(locScenario)}</li>
<li>Happy Path Smoke: ${code(hpScenario)}</li>
</ul>
<p style="font-size: 13px; color: #666;">Via Cekura MCP: <code>cron_jobs_partial_update(${CEKURA_TIER2_CRON_ID}, { scenarios: [...existing, ${locScenario}, ${hpScenario}] })</code></p>
</div>

<!-- TASK 2: CHATDASH -->
<div style="background: #fef3c7; border-left: 4px solid #d97706; padding: 16px 20px; margin: 20px 0; border-radius: 0 8px 8px 0;">
<h3 style="margin-top: 0; color: #92400e;">2. ChatDash Setup</h3>
<ol>
<li><strong>Create Agent</strong> at <a href="https://chat-dash.com" style="color: #1a73e8;">chat-dash.com</a>
  <ul><li>Name: ${code("CNKB-" + centreName)}</li><li>Platform: Retell</li></ul>
</li>
<li><strong>Create Client</strong>
  <ul>
  <li>Name: ${code("Code Ninjas " + centreName)}</li>
  <li>Member name: ${code(ownerName || "&lt;owner_name&gt;")}</li>
  <li>Login ID: ${code(loginId)}</li>
  <li>Email: ${code(email)}</li>
  <li>Password: ${code(password)}</li>
  </ul>
</li>
<li><strong>Assign agent to client</strong></li>
<li><strong>Verify Retell webhook</strong> &mdash; ChatDash auto-sets it when you connect. Check: <code>GET /get-agent/${agentId}</code></li>
<li><strong>Set forwarding URL</strong> in ChatDash agent settings: ${code(N8N_WEBHOOK)}</li>
</ol>
</div>

<!-- TASK 3: HIYA -->
<div style="background: #fef3c7; border-left: 4px solid #d97706; padding: 16px 20px; margin: 20px 0; border-radius: 0 8px 8px 0;">
<h3 style="margin-top: 0; color: #92400e;">3. Register Hiya Branded Caller ID</h3>
<p>Register ${code(phone)} as <strong>Code Ninjas ${centreName}</strong></p>
<p>Go to: <a href="https://hiya.com/branded-caller-id" style="color: #1a73e8;">hiya.com/branded-caller-id</a></p>
