async function step10_onboardingEmail(state: OnboardingState): Promise<void> {
  stepHeader(10, "Client Onboarding Email");

  let centreCode = state.discovery?.centreCode ?? "";
  let director = ownerName;

  // Look up director name and centre code from the sheet if not already known
  if (!director || !centreCode) {
    try {
      info("Looking up director name from centre directory sheet...");
      const csvUrl = `https://docs.google.com/spreadsheets/d/${CENTRE_LOOKUP_SHEET}/gviz/tq?tqx=out:csv`;
      const csvRes = await fetch(csvUrl);
      if (csvRes.ok) {
        const csv = await csvRes.text();
        const rows = csv.split("\n");
        for (const row of rows) {
          // Parse CSV fields properly (handles quoted values)
          const cols: string[] = [];
          let current = "";
          let inQuotes = false;
          for (const ch of row) {
            if (ch === '"') { inQuotes = !inQuotes; continue; }
            if (ch === ',' && !inQuotes) { cols.push(current.trim()); current = ""; continue; }
            current += ch;
          }
          cols.push(current.trim());

          // Match on location_name (column 3) — case-insensitive
          const locationName = cols[3] ?? "";
          if (locationName.toLowerCase() === centreName.toLowerCase()) {
            // Column 0 = centre_id, Column 8 = Director
            if (!centreCode && cols[0]) {
              centreCode = cols[0];
              info(`Found centre code: ${centreCode}`);
            }
            const dirCol = cols[8] ?? "";
            if (!director && dirCol) {
              director = dirCol.split(" ")[0]; // First name only for salutation
              info(`Found director: ${dirCol} (using "${director}" for salutation)`);
            }
            break;
          }
        }
      }
    } catch {
      info("Could not look up from sheet — using available data");
    }
  }

  // Final fallback for centre code
  if (!centreCode) {
    centreCode = centreName.toLowerCase().replace(/\s+/g, "-");
  }

  const fromNumber = (state.twilioNumber ?? "").replace("+", "");
  const subject = `Code Ninjas ${centreName} — Getting Started`;
  const html = buildOnboardingEmailHtml(director, centreCode, centreName, fromNumber);

  if (dryRun) {
    dryLog(`Would send onboarding email to ${ONBOARDING_EMAIL_TO}`);
    dryLog(`Subject: ${subject}`);
    dryLog(`Salutation: "Hi ${director || "there"}"`);
    dryLog(`Centre code in email: ${centreCode}`);
    dryLog(`Forwarding address: scott.james1717+${centreCode}@gmail.com`);
    return;
  }

  info(`Sending onboarding email to ${ONBOARDING_EMAIL_TO}...`);

  const res = await fetch("https://api.resend.com/emails", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${RESEND_API_KEY}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      from: RESEND_FROM,
      to: [ONBOARDING_EMAIL_TO],
      subject,
      html,
    }),
  });

  if (!res.ok) {
    throw new Error(`Resend API failed: ${res.status} ${await res.text()}`);
  }

  const result = await res.json() as { id: string };
  ok(`Onboarding email sent (ID: ${result.id})`);
  info(`Forward to the centre director when ready`);
}

// ─────────────────────────────────────────────────────────────
// Step 11: Hiya — Manual Steps
// ─────────────────────────────────────────────────────────────

function step11_hiya(state: OnboardingState): void {
  stepHeader(11, "Hiya - Branded Caller ID");

  console.log(`
  ${YELLOW}ACTION REQUIRED:${RESET} Register ${BOLD}${state.twilioNumber}${RESET} with Hiya for branded caller ID.

  Display name: ${BOLD}Code Ninjas ${centreName}${RESET}

  Register at: https://hiya.com/branded-caller-id
`);
}

// ─────────────────────────────────────────────────────────────
// Step 12: Summary
// ─────────────────────────────────────────────────────────────

function step12_summary(state: OnboardingState): void {
  stepHeader(12, "Onboarding Summary");

  const pad = (s: string, len: number): string => s.padEnd(len);
  const w = 56;
  const rule = "=".repeat(w);
  const line = (label: string, value: string): string => {
    const content = `  ${pad(label, 22)} ${value}`;
    return `  ${content}`;
  };

  const d = state.discovery;
  console.log(`
  ${GREEN}${BOLD}${rule}${RESET}
  ${GREEN}${BOLD}  ONBOARDING COMPLETE: Code Ninjas ${centreName}${RESET}
  ${GREEN}${BOLD}${rule}${RESET}
${d ? `${line("Centre Code:", d.centreCode)}
${line("City:", `${d.city}, ${d.state}`)}
${line("Address:", d.address)}
${line("Country:", d.country)}
${line("Area Code:", d.areaCode)}
` : ""}${line("Twilio Sub-Account:", state.subAccountSid ?? "FAILED")}
${line("Twilio Number:", state.twilioNumber ?? "FAILED")}
${line("Twilio SID:", state.twilioSid ?? "FAILED")}
${line("SIP Trunk:", state.trunkDomain ?? "FAILED")}
${line("Retell LLM:", state.retellLlmId ?? "FAILED")}
${line("Retell Agent:", state.retellAgentId ?? "FAILED")}
${line("Retell Phone:", state.retellPhoneId ?? "FAILED")}
${line("Cekura Agent:", state.cekuraAgentId?.toString() ?? "FAILED")}
${line("Cekura Loc Scenario:", state.cekuraScenarioLocId?.toString() ?? "FAILED")}
${line("Cekura HP Scenario:", state.cekuraScenarioHpId?.toString() ?? "FAILED")}
${line("ChatDash:", "MANUAL - see Step 8")}
${line("Google Sheet:", state.discovery?.centreCode ?? "see Step 9")}
${line("Onboarding Email:", "Sent to Scott - see Step 10")}
${line("Hiya:", "MANUAL - see Step 11")}
  ${GREEN}${BOLD}${rule}${RESET}
`);

  if (dryRun) {
    console.log(`  ${YELLOW}${BOLD}This was a DRY RUN. No API calls were made.${RESET}`);
  }
}

// ─────────────────────────────────────────────────────────────
// Main Execution
// ─────────────────────────────────────────────────────────────

async function main(): Promise<void> {
  console.log(`\n${BOLD}${CYAN}===============================================${RESET}`);
  console.log(`${BOLD}${CYAN} Code Ninjas Centre Onboarding: ${centreName}${RESET}`);
  console.log(`${BOLD}${CYAN}===============================================${RESET}`);
  if (ownerName) console.log(`  Owner: ${ownerName} <${ownerEmail}>`);
  if (dryRun) console.log(`  ${YELLOW}${BOLD}MODE: DRY RUN${RESET}`);

  const state: OnboardingState = {
    discovery: null,
    subAccountSid: null,
    subAccountToken: null,
    twilioNumber: null,
    twilioSid: null,
    trunkDomain: null,
    trunkSid: null,
    retellLlmId: null,
    retellAgentId: null,
    retellPhoneId: null,
    cekuraAgentId: null,
    cekuraScenarioLocId: null,
    cekuraScenarioHpId: null,
  };

  const completed: string[] = [];
  const failed: string[] = [];

  // Step 0: Discover centre details if area-code not provided
  if (!areaCode) {
    try {
      const discovery = await step0_discover(centreName);
      state.discovery = discovery;
      areaCode = discovery.areaCode;
      country = country ?? discovery.country;
      completed.push("Discovery");
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      fail(msg);
      console.log(`\n${RED}${BOLD}Discovery failed. Provide --area-code and --country manually.${RESET}`);
      process.exit(1);
    }
  } else {
    country = country ?? "CA";
    info(`Using manual area code: ${areaCode}, country: ${country}`);
  }

  console.log(`  Country: ${country} | Area Code: ${areaCode}`);

  // Steps 1-6 are API-dependent and sequential
  const steps: Array<{
    name: string;
    fn: (state: OnboardingState) => Promise<void> | void;
  }> = [
    { name: "Twilio Provision", fn: step1_twilioProvision },
    { name: "Retell LLM", fn: step2_retellLlm },
    { name: "Retell Agent", fn: step3_retellAgent },
    { name: "Retell Phone Import", fn: step4_retellPhone },
    { name: "Cekura Agent", fn: step5_cekuraAgent },
    { name: "Cekura Scenarios", fn: step6_cekuraScenarios },
  ];

  for (const step of steps) {
    try {
      await step.fn(state);
      completed.push(step.name);
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      fail(msg);
      failed.push(step.name);

      // Report partial progress and bail
      console.log(`\n${RED}${BOLD}Onboarding ABORTED at step: ${step.name}${RESET}`);
      console.log(`\n  ${GREEN}Completed:${RESET} ${completed.join(", ") || "none"}`);
      console.log(`  ${RED}Failed:${RESET} ${failed.join(", ")}`);

      if (completed.length > 0) {
        console.log(`\n  ${YELLOW}Partial resources created (may need manual cleanup):${RESET}`);
        if (state.subAccountSid) console.log(`    Twilio Sub-Account: ${state.subAccountSid}`);
        if (state.twilioNumber) console.log(`    Twilio Phone: ${state.twilioNumber} (SID: ${state.twilioSid})`);
        if (state.trunkSid) console.log(`    Twilio Trunk: ${state.trunkSid} (${state.trunkDomain})`);
        if (state.retellLlmId) console.log(`    Retell LLM: ${state.retellLlmId}`);
        if (state.retellAgentId) console.log(`    Retell Agent: ${state.retellAgentId}`);
        if (state.retellPhoneId) console.log(`    Retell Phone: ${state.retellPhoneId}`);
        if (state.cekuraAgentId) console.log(`    Cekura Agent: ${state.cekuraAgentId}`);
      }

      process.exit(1);
    }
  }

  // Step 7-8 are informational (no API calls), always succeed
  step7_cekuraCron(state);
  step8_chatDash(state);

  // Step 9 writes to Google Sheet via n8n webhook
  try {
    await step9_googleSheet(state);
    completed.push("Google Sheet");
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    fail(`Google Sheet update failed: ${msg}`);
    console.log(`  ${YELLOW}Manual fallback:${RESET} Update sheet at https://docs.google.com/spreadsheets/d/${CENTRE_LOOKUP_SHEET}/edit`);
  }

  // Step 10 sends the client onboarding email
  try {
    await step10_onboardingEmail(state);
    completed.push("Onboarding Email");
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    fail(`Onboarding email failed: ${msg}`);
  }

  // Steps 11-12 are informational, always succeed
  step11_hiya(state);
  step12_summary(state);
}

main().catch((err) => {
  console.error(`\n${RED}${BOLD}Fatal error:${RESET}`, err);
  process.exit(1);
});

